window.MANUAL_ROLES=[{"id":"it","label":"IT / 系统管理员","title":"基础环境、现场设备与账号权限","desc":"配置景区、景点、站点、通道、设备、打印、员工与权限。","tasks":[{"title":"基础信息与员工权限","source":"后台培训P4-26","steps":[{"page":4,"title":"基础信息功能简介与配置流程","body":"配置景区：填写景区基本信息，目前主要；用以显示景区名称；配置景点：景区下各个小景点名称配置，主要用；以显示景点名称；配置站点：用以配置检票和售票站点相关信息；配置通道：用以配置各站点下通道；配置设备：用以配置各通道下不同设备，包含了；闸机，窗口售票机，手机（PDA），POS机，；人证设备，自助售票机暂时不可用。；配置角色：用以配置各菜单和按钮权限的角色；配置员工：用以配置员工和部门信息；配置系统角色：主要用以配置窗口售票账号，一；般仅允许管理员配置，且尽量少修改，涉及报表。；配置分成项目：用以配置子票分成和报表数据统；计和展示。；配置打印模板：用以配置散客票和团队票，一人；一票，一票多人以及散客内导和团队内导票。","img":"assets/ppt-mapped/full/后台-票库-P004.png","caption":"后台培训P4-26｜第 4 页"},{"page":5,"title":"基础信息-配置景区","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P005.png","caption":"后台培训P4-26｜第 5 页"},{"page":6,"title":"基础信息-配置景点","body":"特别注意：；景点删除后，基础票对应景点同步删除，基础票需要重新配置，；如无必要不建议删除景点，删除后需要检查所有基础票型有无关联此景点。","img":"assets/ppt-mapped/full/后台-票库-P006.png","caption":"后台培训P4-26｜第 6 页"},{"page":7,"title":"基础信息-配置站点","body":"特别注意：；站点下有通道或设备启用中，不允许删除，订单快照会记录站点 ID和站点名称，删除后，通过 ID会搜索不到，不建议随便删除。","img":"assets/ppt-mapped/full/后台-票库-P007.png","caption":"后台培训P4-26｜第 7 页"},{"page":8,"title":"基础信息-配置通道","body":"特别注意：；通道下有设备启用中，不允许删除，订单快照会记录通道 ID和通道名称，删除后，通过 ID会搜索不到，不建议随便删除。","img":"assets/ppt-mapped/full/后台-票库-P008.png","caption":"后台培训P4-26｜第 8 页"},{"page":9,"title":"基础信息-配置设备","body":"特别注意：；通道下有设备启用中，不允许删除，订单快照会记录通道 ID和通道名称，删除后，通过 ID会搜索不到，不建议随便删除。","img":"assets/ppt-mapped/full/后台-票库-P009.png","caption":"后台培训P4-26｜第 9 页"},{"page":10,"title":"基础信息-配置设备","body":"设备管理页可以单独对所有设备进行查询，筛选，批量设置和进行信息导出，更便于对设备的管理；特别注意：；订单快照会记录设备ID和设备名称，删除后，通过 ID会搜索不到，不建议随便删除。","img":"assets/ppt-mapped/full/后台-票库-P010.png","caption":"后台培训P4-26｜第 10 页"},{"page":11,"title":"基础信息-新增站点/通道/设备","body":"新增站点 新增通道 新增设备","img":"assets/ppt-mapped/full/后台-票库-P011.png","caption":"后台培训P4-26｜第 11 页"},{"page":12,"title":"基础信息-新增站点/通道/设备 – 特殊设备配置","body":"有人证设备的闸机，需要单独添加人证；设备，再绑定到特定闸机；（此部分需要研发确认配置）；设备类型为POS机的，需要绑定到对应窗；口，这样未来可以与建行进行自动对帐；设备类型为扫码枪的，需要绑定到对应窗","img":"assets/ppt-mapped/full/后台-票库-P012.png","caption":"后台培训P4-26｜第 12 页"},{"page":13,"title":"基础信息 – 分成项目","body":"分成管理等同于“项目管理”，体现在后续报表中，体现为“项目名”","img":"assets/ppt-mapped/full/后台-票库-P013.png","caption":"后台培训P4-26｜第 13 页"},{"page":14,"title":"基础信息 – 分成公司","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P014.png","caption":"后台培训P4-26｜第 14 页"},{"page":15,"title":"基础信息 – 关联部门","body":"每个分成项目可以关联不同部门，部门与分成项目的关系为一对多，一个部门可以配置多个分成项目，但一个分成项目仅能配置一个部门；可以在分成项目前勾选后点击“批量管理”进行批量设置。","img":"assets/ppt-mapped/full/后台-票库-P015.png","caption":"后台培训P4-26｜第 15 页"},{"page":16,"title":"基础信息-打印管理","body":"1. 必须先配置模板才能配置对应模板内容；2. 模板必须要设定使用的窗口售票机，如不设置对应窗口打印机不起作用","img":"assets/ppt-mapped/full/后台-票库-P016.png","caption":"后台培训P4-26｜第 16 页"},{"page":17,"title":"基础信息-打印管理-打印模板","body":"1. 按窗口场景一共分6种模板，每种模板仅有一个默认模板，正常按默认模板打印；2. 每个模板必须配置对应窗口售票机，否则不起作用；3. 如果打印机型号不同，请配置不同模板， 每个窗口根据所使用的打印机型号配置对应的 6个模板，如该窗口后续替换了打印机，；请调整窗口配置的6个默认模板","img":"assets/ppt-mapped/full/后台-票库-P017.png","caption":"后台培训P4-26｜第 17 页"},{"page":18,"title":"基础信息-打印管理-内容管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P018.png","caption":"后台培训P4-26｜第 18 页"},{"page":19,"title":"基础信息-打印管理-内容管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P019.png","caption":"后台培训P4-26｜第 19 页"},{"page":21,"title":"员工管理-角色管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P021.png","caption":"后台培训P4-26｜第 21 页"},{"page":22,"title":"员工管理-员工管理-部门管理","body":"1. 配置员工时，点击左侧架构树，先添加部门，点击对应部门名，点击右侧“部门管理”可添加左侧该部门下子部门","img":"assets/ppt-mapped/full/后台-票库-P022.png","caption":"后台培训P4-26｜第 22 页"},{"page":23,"title":"员工管理-员工管理-员工管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P023.png","caption":"后台培训P4-26｜第 23 页"},{"page":24,"title":"员工管理-员工管理-员工管理","body":"1. 每个员工尽量配置真实姓名；2. 配置真实手机号便于自助找回密码；3. 每个员工新建时只能配置一个角色，后续编辑时可以新增多个角色权限","img":"assets/ppt-mapped/full/后台-票库-P024.png","caption":"后台培训P4-26｜第 24 页"},{"page":25,"title":"员工管理-员工管理-系统角色","body":"1. 仅针对窗口售票员的账号管理，一般不改动，否则会影响报表","img":"assets/ppt-mapped/full/后台-票库-P025.png","caption":"后台培训P4-26｜第 25 页"},{"page":26,"title":"员工管理-员工管理-系统角色","body":"新增时，仅能添加手机，可不使用现实手机号，随便配置对应手机位数的号，编辑时，可以修改账号和用户名。；特别注意：账号对应登录账号名，用户名为实际报表显示名称。","img":"assets/ppt-mapped/full/后台-票库-P026.png","caption":"后台培训P4-26｜第 26 页"}]}]},{"id":"ticket","label":"票库人员","title":"产品、规则、价格库存与套票配置","desc":"维护基础票、组合票、套票、规则、价格和库存。","tasks":[{"title":"票务中心：基础票、规则与组合票","source":"后台培训P27-59","steps":[{"page":29,"title":"基础信息 – 分成项目","body":"分成管理等同于“项目管理”，体现在后续报表中，体现为“项目名”","img":"assets/ppt-mapped/full/后台-票库-P029.png","caption":"后台培训P27-59｜第 29 页"},{"page":30,"title":"基础信息 – 分成公司","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P030.png","caption":"后台培训P27-59｜第 30 页"},{"page":31,"title":"基础信息 – 关联部门","body":"每个分成项目可以关联不同部门，部门与分成项目的关系为一对多，一个部门可以配置多个分成项目，但一个分成项目仅能配置一个部门；可以在分成项目前勾选后点击“批量管理”进行批量设置。","img":"assets/ppt-mapped/full/后台-票库-P031.png","caption":"后台培训P27-59｜第 31 页"},{"page":32,"title":"票务中心-基础票管理","body":"特别注意：基础票如已关联了组合票，暂时不允许下架。","img":"assets/ppt-mapped/full/后台-票库-P032.png","caption":"后台培训P27-59｜第 32 页"},{"page":34,"title":"票务中心-基础票管理 – 基础票信息变更注意","body":"特别注意：；1.由于组合票上的信息，特别是检票部分是由基础票确定；的，在组合票保存时会保存下所关联的基础票信息，所以；如基础票信息变更，系统会通过JOB批量更新所关联的组；合票上的信息，目前JOB执行时间为10分钟/次，所以如；变更了基础票，想在组合票上应用，至少需要 等待10分钟。；如希望有部分票型立马变更，需要进入对应组合票重新保；存。；2.基础除了检票通道以外，所有的信息只要下单就会存储；订单快照，所有对应配置信息全部按订单快照执行 。；3.基础票检票通道可以实时变更，同样 变更后等待10分钟；应用到组合票上后，即可使用最新配置的通道检票","img":"assets/ppt-mapped/full/后台-票库-P034.png","caption":"后台培训P27-59｜第 34 页"},{"page":35,"title":"票务中心-基础票管理","body":"下单后是否立即核销选项，需要以下条件才能生效：；1.下单后立即可用；2.不需要窗口换票；3.使用日期包含当天可用","img":"assets/ppt-mapped/full/后台-票库-P035.png","caption":"后台培训P27-59｜第 35 页"},{"page":36,"title":"票务中心-组合票管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P036.png","caption":"后台培训P27-59｜第 36 页"},{"page":37,"title":"票务中心-组合票管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P037.png","caption":"后台培训P27-59｜第 37 页"},{"page":38,"title":"票务中心-组合票管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P038.png","caption":"后台培训P27-59｜第 38 页"},{"page":39,"title":"票务中心-预订规则/消费规则/退票规则","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P039.png","caption":"后台培训P27-59｜第 39 页"},{"page":40,"title":"票务中心-新增预订规则","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P040.png","caption":"后台培训P27-59｜第 40 页"},{"page":41,"title":"票务中心-新增预订规则","body":"一般年龄限制必须要开启身份证；信息录入，但如此时，对应启用；该预订规则的票型需要允许护照；录入，则需要选择“启用年龄限；制是否允许其他证件导入”；如“允许”，则关联此类预订规；则的票型，即使有年龄限制依然；可以使用护照导入，导入信息时；不做控制判断，“不允许”则该；票型购票时不允许填写护照，线；上与线下票同时适用。","img":"assets/ppt-mapped/full/后台-票库-P041.png","caption":"后台培训P27-59｜第 41 页"},{"page":42,"title":"票务中心-新增消费规则","body":"只能使用总库存，不能使用日历库存，且如设定后，不；可再变更为上面两个选项；新功能，此处设置后，该票型购票后不能直接入园，需要在窗口进行；身份验证，确认后方可此处为目前需要核验身份，如海南人，入园，；粉丝票或特殊身份人群设置，所有窗口直接可购的票不要设置，否则；出票后无法打印，需要再次确认；此两种选项可以选择总库存模式和；日历库存模式；当消费规则设置为；下单后立即可用+不需要窗口换票+使用日期包含当天可用时；设置为“是”该组合票下单后全部子票都会自动核销","img":"assets/ppt-mapped/full/后台-票库-P042.png","caption":"后台培训P27-59｜第 42 页"},{"page":43,"title":"票务中心-新增退改规则","body":"1.只要在退改规则里设置了某状态不可退，所有符合条件的门票，都不能走正常退票进行退票，必须走强制退票才行。；2.不可退-下单售出后一律不能正常退票，只能申请强退 ；；3.未取票可退-如已取票即不能正常退票，只能申请强退 ；；4.未消费状态时，有效果期内可退 – 未检票的情况下只要没有过门票 有效期可正常退票，已检票不能正常退票，只能申请强退 。；（目前景区基本使用此规则）；5.未消费均可退款 – 只要未检票，无论是否过了有效期都可以正常退票；特别注意：所有已消费（即已检票的票）都只能申请强退，不在退改规则范围内。","img":"assets/ppt-mapped/full/后台-票库-P043.png","caption":"后台培训P27-59｜第 43 页"},{"page":44,"title":"票务中心-预订规则/消费规则/退票规则","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P044.png","caption":"后台培训P27-59｜第 44 页"},{"page":45,"title":"票务中心-票型种类/价格类型/活动标签配置","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P045.png","caption":"后台培训P27-59｜第 45 页"},{"page":46,"title":"票务中心-新增组合票-基本信息-选择基础票","body":"在此可以选择该组合票的基础子票，输入自；动下拉匹配，勾选后会在下方表格中显示","img":"assets/ppt-mapped/full/后台-票库-P046.png","caption":"后台培训P27-59｜第 46 页"},{"page":47,"title":"票务中心-新增组合票-基本信息","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P047.png","caption":"后台培训P27-59｜第 47 页"},{"page":48,"title":"票务中心-新增组合票-基本信息-选择组合票检票通道","body":"组合票的检票为基础票检票通道与组合票上配置的检票通道的交集，所以；配置了基础票后，检票通道只会显示所有基础票的检票通道，可以减少，；不能增加，如需要细分不同票型检票通道，基础票可以配置大部分，再在；组合票上进行删减。","img":"assets/ppt-mapped/full/后台-票库-P048.png","caption":"后台培训P27-59｜第 48 页"},{"page":49,"title":"票务中心-新增组合票-规则配置","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P049.png","caption":"后台培训P27-59｜第 49 页"},{"page":50,"title":"票务中心-新增组合票-下一步-价格库存-日历库存模式","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P050.png","caption":"后台培训P27-59｜第 50 页"},{"page":51,"title":"票务中心-新增组合票--日历库存模式-单日设置","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P051.png","caption":"后台培训P27-59｜第 51 页"},{"page":52,"title":"票务中心-新增组合票--日历库存模式-批量设置","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P052.png","caption":"后台培训P27-59｜第 52 页"},{"page":53,"title":"票务中心-新增组合票-总库存模式","body":"当选择了消费规则为固定日期时，不允许选择日历库存模式；所有票型一旦设定了库存模式不允许相互调整！其他与日历库存配置一样。","img":"assets/ppt-mapped/full/后台-票库-P053.png","caption":"后台培训P27-59｜第 53 页"},{"page":54,"title":"票务中心-新增组合票-总存库模式-M选N票","body":"特别注意：只有前面分成模式配置成为“按票型设置-检票后分成”才允许配置M选N组合票；【非M选N项目选择】：此部分；下拉可选择该组合票中所有非；M选N项的基础票；【M选N项目数】：填写该组合票需要包含的M选N项目，最多5个, M选N项目数填写几个，；下方出现几个M选N项目；门+车+3选1（项目名2+项目名2+项目名3）+4选1（项目名2+项目名2+项目名3+项目；名4）其中，3选1（项目名2+项目名2+项目名3）和4选1（项目名2+项目名2+项目名3+；项目名4）都是M选N项目，项目数为2；M/N 数值（包含多少个基础票/允许检多少个）；项目1M项选择，第一个M选N中M项目的基础票配置 （M选N组编号以此类推）；该M选N项目未检或盈利金额全部进入此分项目，可以所有M选N项全部一致，也；可以各项目配置不同的分成项目，为了更方便统计，建议拆分->增加独立的缆车；未检或盈利分成项目。；非M选N项目价=所有已选为”非M选N项目“子票分成价格总和（根据后面表格所填写的分成金额实时计算）；M选N项目1价（此处1为序号，按项目数量依次累计）= 该项目内按分成价格降序取前 N 个的总和；售卖价格= 非 M 选N项价 + 所有 M 选N项价相加总和","img":"assets/ppt-mapped/full/后台-票库-P054.png","caption":"后台培训P27-59｜第 54 页"},{"page":55,"title":"票务中心-新增组合票-总存库模式-M选N票","body":"默认为空，不加载数据，“非M选N项选择”，“项目1M选择”，按上页中中每加入一个基础票，在表格中体现对应基础票信息，且以“非M选N项目”，“M选N；项目1”，“M选N项目2”等项目归类。","img":"assets/ppt-mapped/full/后台-票库-P055.png","caption":"后台培训P27-59｜第 55 页"},{"page":56,"title":"票务中心-新增组合票-总存库模式-M选N票 –缆车票注意","body":"如M项中包含基础票类型为“缆车票”的，该M项中必须所有都是缆车票。；如包含了缆车的组合票，调整了项目数，索道方可以识别到并需要进行审核；如当前缆车在项目1中，调整到了项目2中，也会触发索道方审核机制；如M；如当前组合票内缆车票减少或增加，会触发索道方审核机制","img":"assets/ppt-mapped/full/后台-票库-P056.png","caption":"后台培训P27-59｜第 56 页"},{"page":57,"title":"票务中心-新增组合票-总存库模式-M选N票 –案例","body":"门+项目1+项目2+车2上/车2下（2选1）+缆车1号线上行/缆车1号线下行/缆车2号线(上行)/缆车2号线(下行) (4选1)+戏水/滑索/穿越热带雨林(3选2)；非M选N项：门=30，项目1=10，项目2=10；M选N项1（2选1）：车2上=40，车2下=30；M选N项2（4选1）：缆车1号线上行=80，缆车1号线下行=80，缆车2号线(上行) =80，缆车2号线(下行) =80；M选N项3（3选2）：戏水=30，滑索=40，穿越雨林=50；非M选N项价格=所有”非M选N项目“子票价格总和=门+项目1+项目2=50；M选N项1价格（N=1）=该项目内按价格降序取前 N 个的总和=40；M选N项2价格（N=1）=该项目内按价格降序取前 N 个的总和=80；M选N项3价格（N=2）=该项目内按价格降序取前 N 个的总和=50+40=90；该组合票总价格=非 M 选N项价 + 所有 M 选N项价相加总和=40+80+90=210","img":"assets/ppt-mapped/full/后台-票库-P057.png","caption":"后台培训P27-59｜第 57 页"},{"page":58,"title":"票务中心-新增组合票-总存库模式-M选N票 –案例","body":"门+缆车1号线上行/缆车1号线下行（2选1）+缆车2号线(上行)/ 缆车2号线(下行) （2选1） +戏水/滑索/穿越热带雨林(3选2)；非M选N项：门=30；M选N项1（2选1）：缆车1号线上行=80，缆车1号线下行=80；M选N项2（2选1）：缆车2号线(上行)=80，缆车2号线(下行) =80；M选N项3（3选2）：戏水=30，滑索=40，穿越雨林=50；非M选N项价格=所有”非M选N项目“子票价格总和=门=30；M选N项1价格（N=1）=该项目内按价格降序取前 N 个的总和=80；M选N项2价格（N=1）=该项目内按价格降序取前 N 个的总和=80；M选N项3价格（N=2）=该项目内按价格降序取前 N 个的总和=50+40=90；该组合票总价格=非 M 选N项价 + 所有 M 选N项价相加总和=30+80+80+90=280；门+缆车1号线上行+缆车1号线下行/缆车2号线(上行)/ 缆车2号线(下行) （3选2）；非M选N项：门30+缆车1号线上行80=110；M选N项1（2选1）：60+60=120；该组合票总价格=非 M 选N项价 + 所有 M 选N项价相加总和=110+120=230","img":"assets/ppt-mapped/full/后台-票库-P058.png","caption":"后台培训P27-59｜第 58 页"},{"page":59,"title":"票务中心-组合票查询","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P059.png","caption":"后台培训P27-59｜第 59 页"}]},{"title":"票务中心：缆车票配置","source":"后台培训P60-69","steps":[{"page":61,"title":"缆车票推送字段说明","body":"组合产品查询接口 下单接口","img":"assets/ppt-mapped/full/后台-票库-P061.png","caption":"后台培训P60-69｜第 61 页"},{"page":62,"title":"缆车票推送字段说明","body":"退票接口；缆车票检票接口","img":"assets/ppt-mapped/full/后台-票库-P062.png","caption":"后台培训P60-69｜第 62 页"},{"page":63,"title":"缆车票推送字段说明","body":"门区检票接口；门区检票记录查询接口","img":"assets/ppt-mapped/full/后台-票库-P063.png","caption":"后台培训P60-69｜第 63 页"},{"page":64,"title":"缆车票 – 原下单和校验情况","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P064.png","caption":"后台培训P60-69｜第 64 页"},{"page":65,"title":"缆车票 – 功能更新后下单和校验情况","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-票库-P065.png","caption":"后台培训P60-69｜第 65 页"},{"page":66,"title":"缆车票功能配置","body":"库存模式为:总库存；且组合票中包含了基础票门票类型为“缆车票”；的所有组合票，都会有此功能按钮。；代表该缆车票可以配置独立给到索道的单缆车票；如不配置，订单会按原方式走，该组合票必须要经过缆车审核；可以通过此筛选项，查看；哪些缆车票已绑定了需要单独推送给缆车的“缆车组合票”；哪些还未绑定，该组合票必须要通过索道方的审核。","img":"assets/ppt-mapped/full/后台-票库-P066.png","caption":"后台培训P60-69｜第 66 页"},{"page":67,"title":"缆车票功能配置","body":"当前所选组合票相关信息；如果组合票中有门票的，需要单独配置对应的独立门票组合票；配置后，这此组合票中的门票最终在下单时对应的门票组合票，就会是此；处配置的门票组合票；特别注意：；1.绑定的门票组合票基础票编码必须与当前组合票中门票基础票编码一致,；价格一致！；2.门票也要区分团散，与当前组合票团散一致！；3.可售日期需要>=当前组合票可售日期；绑定缆车组合票配置后，该组合票最终在下单时对应的缆车票，就会是此；处配置的缆车组合票；1.绑定的缆车组合票中的基础票编码必须与当前所选的组合票中基础票编；码一致，数量一致，价格一致，能一一对应；2.缆车票区分团散，需要与当前组合票团散一致！","img":"assets/ppt-mapped/full/后台-票库-P067.png","caption":"后台培训P60-69｜第 67 页"},{"page":68,"title":"缆车票上线准备工作及注意事项","body":"1.同步缆车的票型确认：；（1）由于新票型添加后3分钟缆车就会拉取，会导致新票型还未来得及绑定缆车组合票缆车就已同步，为避免此种情况，研发暂时做；了同步白名单，只有在白名单中的缆车票才会同步给索道方，所以后续新上票型，在售卖前，需要确认是否是需要缆车审核的票型，；如需要，则要通知研发加入白名单。但如是现已同步过且审核过的缆车票则不需要。；（2）目前白名单中票型为共享文档中“是否为缆车票”标注为“是”的票，请确认。；（3）以上同步的票如有新增，暂时需要联系研发新增。；2.确认同步给缆车的独立组合票（非M选N）；（1）未来需要单独同步给索道方的独立缆车组合票。散客（缆车1号上行，缆车1号下行，缆车2号上行，缆车2号下行，缆车联程）；；团队（缆车1号上行，缆车1号下行，缆车2号上行，缆车2号下行，缆车联程），需要 确认所有独立缆车组合票门票编码 ，并确保索道；方也审核通过（如审核不通过，所有此类票都会在检票时受阻）；（2）未来需要单独同步给索道方的独立门票组合票，区分团散，目前只有散客组合票，无团队，需要建立，需要 确认所有所有独立门；票组合票编码；（3）可以考虑未来，把这些票型有效期延长，通知缆车方审核，这样就不用一致到期修改这些组合票了。不一定需要跟着现有组合票；的有售卖时间走。","img":"assets/ppt-mapped/full/后台-票库-P068.png","caption":"后台培训P60-69｜第 68 页"},{"page":69,"title":"缆车票上线准备工作及注意事项","body":"3.填写统计表，确保配置无问题。；https://doc.weixin.qq.com/sheet/e3_ADIAzQYhAHECNyXxpNxPjQ6G0vIFt?scode=AEUAsQc -；AA4k1pug4iADIAzQYhAHE&tab=BB08J2；此处为判断是否能让索道方获取到的票型；为“是”，则索道可以获取到；此处为判断是否为未来独立推送给；索道方的缆车组合票，为“是”，；给到研发，研发配置，后续可在缆；车组合票配置的弹窗下拉中出现。；此处为判断该组合票是；否在系统中绑定了独立；推送的缆车组合票；为“是”，则是已绑定。；此处填写该组合票；绑定的缆车组合票；编码和名称，无未；绑定不填写；绑定的门票组合票","img":"assets/ppt-mapped/full/后台-票库-P069.png","caption":"后台培训P60-69｜第 69 页"}]},{"title":"套票在票务中心的配置","source":"套票全流程培训","steps":[{"page":1,"title":"呀诺达-程票票票务系统","body":"换票流程优化专项说明与操作手册；2026/3/31","img":"assets/ppt-mapped/full/套票-全流程-P001.png","caption":"套票全流程培训｜第 1 页"},{"page":2,"title":"窗口换票流程优化专项","body":"背景和目标","img":"assets/ppt-mapped/full/套票-全流程-P002.png","caption":"套票全流程培训｜第 2 页"},{"page":3,"title":"背景和目标说明","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P003.png","caption":"套票全流程培训｜第 3 页"},{"page":4,"title":"背景和目标说明","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P004.png","caption":"套票全流程培训｜第 4 页"},{"page":5,"title":"背景和目标说明","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P005.png","caption":"套票全流程培训｜第 5 页"},{"page":8,"title":"窗口换票流程优化专项","body":"涉及部门和配置流程说明","img":"assets/ppt-mapped/full/套票-全流程-P008.png","caption":"套票全流程培训｜第 8 页"},{"page":9,"title":"各部门职责和配置流程","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P009.png","caption":"套票全流程培训｜第 9 页"},{"page":12,"title":"套票管理配置– 总库存模式","body":"在此配置页，主要用于选择所打包套票的子票，该页面中的组合票仅为目前上架中的组合票，已下架的组合票不包含，务必注意所选子票的库存模式、消费规则和退改；规则必须一致。左侧选择套票后，在右侧出现该套票包含的子票，目前最多可打包5种组合票子票，每个子票目前仅允许打包10张，举例即为：10大10小套票；特别注意：售卖日期截止日期必须一致，开始日期在售卖日期的起始日期当日之前的，所勾选票的售卖日期比对范围为：当日00：00：00 - 勾选门票配置的售卖截止时；间。如售卖日期的起始日期在当日当之后的，按所勾选门票配置的起始-截止日期比对。；点击“组合票规则”，查看该门票配置的所有规则；所选套票的子票，消费规则和退改规则必须一致，否则；是不能一并选择打包的，勾选会置灰显示；不一致；搜索所要打包的套票子票；勾选所需要；打包的子票；1；2；3；5；选择套票包含的该子票数量，；如成人票2张；选择套票实名制要求4","img":"assets/ppt-mapped/full/套票-全流程-P012.png","caption":"套票全流程培训｜第 12 页"},{"page":17,"title":"套票配置举例 – 总库存模式","body":"套票售卖价=所有所选组合票售卖价之和（各组合票单价*<套票配置的组合票数量>之和），列表中数量可增加或减少，如列表中组合票数量变动，此处实时变更；总库存：套票的总库存由库存最紧张的子票决定。系统会计算每种子票目前的库存最多能凑出多少个套票 ，然后取最低值。；特别注意：套票后续分成价格等，按每个子票统计拆分，分成也按原子票分成统计，逻辑不变。；套票需要设置主票，如套票仅允许填写一位游客信息，一般会配置；到主票上，所以此处的主票配置仅用于针对一位游客时身份信息给；到哪张子票的设置，建议可设置为年龄限制为成人的子票。；一个套票需要“2张成人票+1张儿童票”。当前成人票有16张（能凑8；套），儿童票有10张（能凑10套）。受限于成人票的数量，该套票最；多只能凑出8套，因此套票总库存显示为8。；自动获取该套票中所有子票交集时间；新增套票时默认为否，后续延期编辑套票时可用 点击“保存”新建套票","img":"assets/ppt-mapped/full/套票-全流程-P017.png","caption":"套票全流程培训｜第 17 页"},{"page":18,"title":"消费规则新增配置说明","body":"如下单规则中只有一票一人证件信息的场景，为配合入园实名制要求且不阻碍已有证件游客的入园，增加窗口确认限制配置。此种场景可配置为“有证件不需要窗口确认/；换票，无证件需要窗口确认/换票”；如此配置，所有下单套票的有证件游客可直接刷证入园，无证件游客必须去窗口进行身份证补录。；建议所有套票子票消费规则全部配置为此。否则刷电子二维码即可入园 -- 如这样配置业务确认下窗口目前售卖的子票是否必填身份证，如有未录的，窗口售出的票依可能；需要进入线上票确认页再次确认。","img":"assets/ppt-mapped/full/套票-全流程-P018.png","caption":"套票全流程培训｜第 18 页"},{"page":19,"title":"套票管理配置 – 日历库存模式","body":"日历库存模式与总库存模式不一致的点；1.不显示售卖单价；2.售卖日期是按每个门票配置的首个日历日期起始，最后一个日历日期截止。此处售卖日期范围的判断逻辑同总库存","img":"assets/ppt-mapped/full/套票-全流程-P019.png","caption":"套票全流程培训｜第 19 页"},{"page":20,"title":"套票管理配置 – 日历库存模式","body":"日历库存模式与总库存模式不一致的点：；日历套票会校验日历库存，每个套票中的子票，每个组合票的日历库存>0的日期必须一致！如不一致请重新配置调整，否则无法正常下单。","img":"assets/ppt-mapped/full/套票-全流程-P020.png","caption":"套票全流程培训｜第 20 页"},{"page":21,"title":"套票配置举例 –日历库存模式","body":"日历库存模式与总库存模式不一致的点：；1.每个子票无售卖价格显示；2.日历库存售卖价和库存按天显示，所以可以点击“查看”弹出日历框查看，如看单天的，可以再点单天，查看所选日期各组合票库存与价格","img":"assets/ppt-mapped/full/套票-全流程-P021.png","caption":"套票全流程培训｜第 21 页"},{"page":22,"title":"套票查询","body":"套票可按套票名与套票编码查询，也可按套票所包含的子票名和子票编码查询；；套票编码与组合票编码区别：套票编码后缀有 –CT；套票售卖价格和库存查看，需要点击“获取”按钮获取最新信息，总库存统一显示/日历库存按日历显示。","img":"assets/ppt-mapped/full/套票-全流程-P022.png","caption":"套票全流程培训｜第 22 页"},{"page":23,"title":"套票导出","body":"套票导出表与组合票导出表区别：；依然按组合票罗列，但每个组合票前会显示该组合票对应的套票编码，套票名称和套票分类","img":"assets/ppt-mapped/full/套票-全流程-P023.png","caption":"套票全流程培训｜第 23 页"},{"page":24,"title":"组合票编辑校验","body":"套票中的组合票有以下变更不允许在套票上架时进行变更，必须要先下架套票才允许编辑；1.日历库存与总库存切换变更 2.组合票中，消费规则，退改规则变更 3.日历日期调整 4.售卖日期调整；特别注意：组合票价格允许变更，但变更后对应套票价格也会同步变更！","img":"assets/ppt-mapped/full/套票-全流程-P024.png","caption":"套票全流程培训｜第 24 页"},{"page":25,"title":"套票中组合票预订规则编辑校验","body":"已上架套票中的组合票配置的预订规则中“是否实名/验证信息/预订限制/性别限制/启用年龄限制是否允许其他证件导入/生日限制”这些条件有变更，必；须将对应套票下架后才允许变更。","img":"assets/ppt-mapped/full/套票-全流程-P025.png","caption":"套票全流程培训｜第 25 页"},{"page":26,"title":"组合票下架与删除","body":"组合票下架系统会自动检查该组合票是否有已上架的套票，如有，不允许下架，必须先下架相关套票；删除组合票系统会自动检查该组合票是否有已上架的套票，如有，不允许删除，必须先下架相关套票；套票上架时，如当前子票售卖日期交集不等于套票售卖日期范围，也会校验，并提示：“该套票子票售卖日期范围变更，请重新编辑该套票再上架。","img":"assets/ppt-mapped/full/套票-全流程-P026.png","caption":"套票全流程培训｜第 26 页"},{"page":27,"title":"套票变更售卖日期","body":"套票上架时，如其子票编辑过且当前售卖日期交集不等于套票售卖日期范围，会提示：“该套票子票售卖日期范围变更，请重新编辑该套票再上架。；由于子票的截止日期必须一致，想套票整体延期，可选择套票中“是否调整子票售卖日期”为“是”，统一填写结束日期即可，点保存后，会统一调整所有子票；的售卖日期。开始日期也可统一调整，但延期一般无需要填写，不填写不会覆盖原开始时间数据。","img":"assets/ppt-mapped/full/套票-全流程-P027.png","caption":"套票全流程培训｜第 27 页"},{"page":30,"title":"套票现场售卖","body":"套票支付确认时，显示所有套票购买的子票明细，2大1小套票购买2张，即4张成人票，2张儿童票，如限定年龄，主票为儿童票，即子票4张，主票2张。；套票一人一票按其内子票分别打印，一票多人即按票型打印","img":"assets/ppt-mapped/full/套票-全流程-P030.png","caption":"套票全流程培训｜第 30 页"},{"page":31,"title":"套票查询","body":"套票票号结构：；XXXX-CT – 代表了套票的主票号，所有OTA由于只设置1张票，所以在OTA上的游客券码都为此票号 例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号，子票号后面会有&+编号 例：主票号&编号","img":"assets/ppt-mapped/full/套票-全流程-P031.png","caption":"套票全流程培训｜第 31 页"},{"page":32,"title":"查看套票订单","body":"所有是套票类的门票，在订单详情中都会在门票名称前标注“套票”，点击“套票”可弹框查看套票名称和套票编码。；目前套票的打印序号保持了原来订单的打印序号处理，即按每个票型进行打印序号编码，但排序上，目前会先按套票排序显示，一家人的票需要在一起，然后再按；门票名称打印序号排序","img":"assets/ppt-mapped/full/套票-全流程-P032.png","caption":"套票全流程培训｜第 32 页"},{"page":37,"title":"套票查询","body":"套票票号结构：；XXXX-CT – 代表了套票的主票号，所有OTA由于只设置1张票，所以在OTA上的游客券码都为此票号 例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号，子票号后面会有&+编号 例：主票号&编号","img":"assets/ppt-mapped/full/套票-全流程-P037.png","caption":"套票全流程培训｜第 37 页"},{"page":38,"title":"查看套票订单","body":"所有是套票类的门票，在订单详情中都会在门票名称前标注“套票”，点击“套票”可弹框查看套票名称和套票编码。；目前套票的打印序号保持了原来订单的打印序号处理，即按每个票型进行打印序号编码，但排序上，目前会先按套票排序显示，一家人的票需要在一起，然后再按；门票名称打印序号排序","img":"assets/ppt-mapped/full/套票-全流程-P038.png","caption":"套票全流程培训｜第 38 页"},{"page":41,"title":"配置套票分销商","body":"票库配置完成套票后，首先需要在分销商管理中配置授权的套票，找到对应的分销商，点击“套票管理”进入配置页面","img":"assets/ppt-mapped/full/套票-全流程-P041.png","caption":"套票全流程培训｜第 41 页"},{"page":42,"title":"配置套票分销商","body":"所有套票都会在此页面显示，可以搜索需要授权的套票，“绑定”套票，如不需要对该分销商授权该套票，可以“解绑”，解绑后分销商将不能再下单。；如需要查看当前该套票的库存设置与价格，可以点击“获取”按钮，查看实时库存与当前价格；如忘记在分销商中绑定套票，仅在全域替换；了编码，则游客下单时会拦截并提示。","img":"assets/ppt-mapped/full/套票-全流程-P042.png","caption":"套票全流程培训｜第 42 页"},{"page":43,"title":"全域-散客票配置","body":"全域 – 官网小程序需要配置套票只需要将原票务系统产品ID，替换为套票编码；特别注意：套票编码格式后缀有“-CT”","img":"assets/ppt-mapped/full/套票-全流程-P043.png","caption":"套票全流程培训｜第 43 页"},{"page":45,"title":"全域-官网小程序散客下单 – 单票下单","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P045.png","caption":"套票全流程培训｜第 45 页"},{"page":46,"title":"全域-官网小程序散客下单 – 多票型合并下单","body":"如多票型下单；系统自动拆分；成多个订单","img":"assets/ppt-mapped/full/套票-全流程-P046.png","caption":"套票全流程培训｜第 46 页"},{"page":48,"title":"全域-官网小程序散客下单 – 1张票3位游客信息","body":"套票票号结构：；XXXX-CT – 代表了套票的主票号，所有OTA由于只设；置1张票，所以在OTA上的游客券码都为此票号；例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号；子票号后面会有&+编号 例：主票号&编号","img":"assets/ppt-mapped/full/套票-全流程-P048.png","caption":"套票全流程培训｜第 48 页"},{"page":49,"title":"全域-官网小程序散客下单 – 1张票1位游客信息","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P049.png","caption":"套票全流程培训｜第 49 页"},{"page":50,"title":"全域-官网小程序散客下单 – 1张票1位游客信息","body":"来几位游客补录几位，不强制要求必须补录证件，完成后点击“确认”后，游客方可入园（刷证或刷纸质票或刷电子二维码）","img":"assets/ppt-mapped/full/套票-全流程-P050.png","caption":"套票全流程培训｜第 50 页"},{"page":51,"title":"套票短信模板配置","body":"增加“套票名称/套票价格/套票购买数量/套票主票号”4个模板参数；如套票的短信会按套票的主票所配置的模板来发送短信","img":"assets/ppt-mapped/full/套票-全流程-P051.png","caption":"套票全流程培训｜第 51 页"},{"page":64,"title":"套票报表统计说明","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P064.png","caption":"套票全流程培训｜第 64 页"}]}]},{"id":"window","label":"售票员 / 收银员","title":"售票、取票、确认、退票、套票与冲红","desc":"完成窗口登录、散客/团队售票、取票、线上确认、退票和现场查询。","tasks":[{"title":"窗口登录、售票、取票与退票","source":"窗口V4 P4-39","steps":[{"page":5,"title":"售票窗口- 登录","body":"使用账号登录后，该账号会默认绑定当前窗口，点；击“确认登录”后登录，如发现所需要登录窗口与；当前窗口不匹配，可联系IT处理。；目前每个窗口都匹配唯一的账号进行登录。如需要；替换账号所绑定的窗口请联系IT。；取票，线上票确认，退票等数据，所有窗口皆可查。","img":"assets/ppt-mapped/full/窗口-操作手册-P005.png","caption":"窗口V4 P4-39｜第 5 页"},{"page":6,"title":"售票窗口- 散客售票","body":"按条件筛选门票，；点击查询下方展示；可售门票；售票功能；散客售票 勾选后，显示价格类型和票型票种，不勾选不显示；游客导入信息模板下载；实名制标识 选择支付方式；导入游客信息；当前窗口最近一笔散客订单信息","img":"assets/ppt-mapped/full/窗口-操作手册-P006.png","caption":"窗口V4 P4-39｜第 6 页"},{"page":7,"title":"售票窗口- 散客售票-游客信息导入","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P007.png","caption":"窗口V4 P4-39｜第 7 页"},{"page":8,"title":"售票窗口- 散客售票-支付确认","body":"选择打印方式，一人一票还是一票多人，可以先选择方式，如后续不需要打印，还会弹出是否打印提示。；选择支付方式此处务必输入实收现金，；旁边系统自动核算出找零，；给到游客即可。 最后点击确认出票；此处为游客应；付金额总数","img":"assets/ppt-mapped/full/窗口-操作手册-P008.png","caption":"窗口V4 P4-39｜第 8 页"},{"page":9,"title":"售票窗口- 散客售票-支付方式说明","body":"扫码付对应当前窗口扫码牌支付金额；银行卡对应当前窗口配置的POS机支付金额；微信和支付宝对应该窗口工作人员手机上安装的老板来了软件上对应的支付金额；散客窗口的挂帐和预付款仅做款项记录，无其他对应功能；聚合支付直连建行扫码枪，弹出“填写支付码”页面，扫码支付。","img":"assets/ppt-mapped/full/窗口-操作手册-P009.png","caption":"窗口V4 P4-39｜第 9 页"},{"page":11,"title":"售票窗口- 团队售票","body":"选择旅行社；售票功能；团队售票；选择导游；点击查询，查询该旅行；社可下单的门票","img":"assets/ppt-mapped/full/窗口-操作手册-P011.png","caption":"窗口V4 P4-39｜第 11 页"},{"page":12,"title":"售票窗口- 团队售票 – 选旅行社","body":"售票功能团队售票","img":"assets/ppt-mapped/full/窗口-操作手册-P012.png","caption":"窗口V4 P4-39｜第 12 页"},{"page":13,"title":"售票窗口- 团队售票 – 选导游","body":"售票功能团队售票","img":"assets/ppt-mapped/full/窗口-操作手册-P013.png","caption":"窗口V4 P4-39｜第 13 页"},{"page":14,"title":"售票窗口- 团队售票 – 未查询到导游，后台添加","body":"登录程程票管理后台添加导游 https://lvyou-ticket.ly.com/#/login/index；在后台添加后，前台即可查询到该导游","img":"assets/ppt-mapped/full/窗口-操作手册-P014.png","caption":"窗口V4 P4-39｜第 14 页"},{"page":15,"title":"售票窗口- 团队售票 – 选票下单","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P015.png","caption":"窗口V4 P4-39｜第 15 页"},{"page":16,"title":"售票窗口- 团队售票-支付确认","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P016.png","caption":"窗口V4 P4-39｜第 16 页"},{"page":18,"title":"售票窗口- 游客取票","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P018.png","caption":"窗口V4 P4-39｜第 18 页"},{"page":19,"title":"售票窗口- 游客取票","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P019.png","caption":"窗口V4 P4-39｜第 19 页"},{"page":20,"title":"售票窗口- 门票详情页","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P020.png","caption":"窗口V4 P4-39｜第 20 页"},{"page":21,"title":"售票窗口功能操作说明","body":"线上票确认；特殊身份或证件线上票核实","img":"assets/ppt-mapped/full/窗口-操作手册-P021.png","caption":"窗口V4 P4-39｜第 21 页"},{"page":22,"title":"售票窗口- 线上票确认","body":"原一些需要验证身份的线上票，如票库配置了需要窗口确认，游客不能直接入园，需要到窗口后，售票员点击“线上票确认”按钮，在；此界面进行身份核实，可以通过三方订单号，游客姓名，证件号其他条件查询，“销售来源”如为线上渠道可以填写分销商或旅行社名。；如订单状态为“待确认”说明还未确认过，如已取票，说明该订单中一定有门票已取票。","img":"assets/ppt-mapped/full/窗口-操作手册-P022.png","caption":"窗口V4 P4-39｜第 22 页"},{"page":23,"title":"售票窗口- 线上票确认","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P023.png","caption":"窗口V4 P4-39｜第 23 页"},{"page":24,"title":"售票窗口功能操作说明","body":"未检票正常退票；已检票强制退票","img":"assets/ppt-mapped/full/窗口-操作手册-P024.png","caption":"窗口V4 P4-39｜第 24 页"},{"page":25,"title":"售票窗口- 散客退票流程","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P025.png","caption":"窗口V4 P4-39｜第 25 页"},{"page":26,"title":"售票窗口- 团队退票流程","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P026.png","caption":"窗口V4 P4-39｜第 26 页"},{"page":27,"title":"售票窗口- 正常退票","body":"1.正常退票仅能退窗口售出的票，线上渠道的未检票不能在此退票；2.可以跨窗口进行退票","img":"assets/ppt-mapped/full/窗口-操作手册-P027.png","caption":"窗口V4 P4-39｜第 27 页"},{"page":28,"title":"售票窗口- 正常退票","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P028.png","caption":"窗口V4 P4-39｜第 28 页"},{"page":29,"title":"售票窗口- 正常退票","body":"1.在弹窗中点击退票即退票成功，所以务必确认清晰；2.每个订单可以分多次退票，每次退票提交一次就会生成一个售后订单，对应每一次提交的所有门票。","img":"assets/ppt-mapped/full/窗口-操作手册-P029.png","caption":"窗口V4 P4-39｜第 29 页"},{"page":30,"title":"售票窗口- 散客/团队强制退票 – 线下票查询","body":"散客线下票或团队线上/线下票，可全部在售票窗口的“退票-强退申请”中进行申请","img":"assets/ppt-mapped/full/窗口-操作手册-P030.png","caption":"窗口V4 P4-39｜第 30 页"},{"page":31,"title":"售票窗口- 散客/团队强制退票 – 线下票退票选择","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P031.png","caption":"窗口V4 P4-39｜第 31 页"},{"page":32,"title":"售票窗口- 散客/团队强制退票 – 线下票提交申请","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P032.png","caption":"窗口V4 P4-39｜第 32 页"},{"page":33,"title":"售票窗口- 线下票强退审批","body":"领导在后台散客售后或团队售后审核中进行审批，通过后返回窗口确认","img":"assets/ppt-mapped/full/窗口-操作手册-P033.png","caption":"窗口V4 P4-39｜第 33 页"},{"page":34,"title":"售票窗口- 强退确认","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P034.png","caption":"窗口V4 P4-39｜第 34 页"},{"page":35,"title":"售票窗口- 散客/团队强制退票 – 线上票","body":"散客线上票，需要在票务系统后台进行申请","img":"assets/ppt-mapped/full/窗口-操作手册-P035.png","caption":"窗口V4 P4-39｜第 35 页"},{"page":36,"title":"售票窗口- 散客/团队强制退票 – 线上票","body":"团队线上票也可在票务系统后台进行申请","img":"assets/ppt-mapped/full/窗口-操作手册-P036.png","caption":"窗口V4 P4-39｜第 36 页"},{"page":37,"title":"售票窗口- 散客/团队强制退票 – 线上票","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P037.png","caption":"窗口V4 P4-39｜第 37 页"},{"page":38,"title":"售票窗口- 散客/团队强制退票 – 线上票","body":"线上票申请提交后，审批通过即可退票","img":"assets/ppt-mapped/full/窗口-操作手册-P038.png","caption":"窗口V4 P4-39｜第 38 页"},{"page":39,"title":"售票窗口- 强退线上票审批","body":"领导在后台散客/团队售后审核中进行审批，审批通过后即可完成退票","img":"assets/ppt-mapped/full/窗口-操作手册-P039.png","caption":"窗口V4 P4-39｜第 39 页"}]},{"title":"窗口销售记录与冲红","source":"窗口V4 P64-80","steps":[{"page":64,"title":"售票窗口功能操作说明","body":"冲红功能/销售记录查看","img":"assets/ppt-mapped/full/窗口-操作手册-P064.png","caption":"窗口V4 P64-80｜第 64 页"},{"page":65,"title":"售票窗口-统计-销售记录","body":"售票窗口 – 统计 –销售记录页，主要用来让售票员可以方便查询到从当前登录账号售出的所有订单销售记录；在此页面中会按订单下单时间倒序排列","img":"assets/ppt-mapped/full/窗口-操作手册-P065.png","caption":"窗口V4 P64-80｜第 65 页"},{"page":66,"title":"售票窗口-统计-销售记录-打印门票","body":"通过 统计 – 销售记录/冲红申请 列表页 –点击“查看”进入“订单详情”页，可以进行批量或单门票打印。；可以根据不同条件查询游客信息","img":"assets/ppt-mapped/full/窗口-操作手册-P066.png","caption":"窗口V4 P64-80｜第 66 页"},{"page":67,"title":"售票窗口-统计-冲红申请使用场景说明","body":"冲红功能可以使用的订单范围和场景：已支付成功，未退票、未使用聚合支付且不在冲红审核中的的所有订单；1.订单状态为：待使用，待确认，已取票，已检票，已完成 2.支付类型不为聚合支付；冲红功能支持多次申请，如前一次冲红已审核完成（同意/驳回皆可），可以进行重新申请","img":"assets/ppt-mapped/full/窗口-操作手册-P067.png","caption":"窗口V4 P64-80｜第 67 页"},{"page":68,"title":"售票窗口-统计-冲红申请","body":"点击“冲红申请”按钮，弹出冲红申请页面，选择申请后需要调整的支付类型，填写原因，提交申请；特别说明：如冲红功能从现金类支付方式调整到预付款或签单，在申请时会判断旅行社的账户余额或授信额；度是否足够，如不够，提交会提示余额不足，需要联系预订部进行充值后才可进行冲红。","img":"assets/ppt-mapped/full/窗口-操作手册-P068.png","caption":"窗口V4 P64-80｜第 68 页"},{"page":69,"title":"售票窗口-统计-冲红审核","body":"冲红需要在票务系统后台-冲红管理-冲红审核菜单 – 待审批中进行审核；登录地址：https://lvyou-ticket.ly.com","img":"assets/ppt-mapped/full/窗口-操作手册-P069.png","caption":"窗口V4 P64-80｜第 69 页"},{"page":70,"title":"售票窗口-统计-冲红审核 – 同意","body":"特别说明：如冲红功能从现金类支付方式调整到预付款或签单，在审核时也会判断旅行社的账户余额或授信；额度是否足够，如不够，提交会提示余额不足，需要联系预订部进行充值后才可进行冲红。；完成冲红是以审核通过为最终节点的，如未审核或审核驳回，该订单的支付方式不变。","img":"assets/ppt-mapped/full/窗口-操作手册-P070.png","caption":"窗口V4 P64-80｜第 70 页"},{"page":71,"title":"售票窗口-统计-冲红审核 – 驳回","body":"完成冲红是以审核通过为最终节点的，如未审核或审核驳回，该订单的支付方式不变。","img":"assets/ppt-mapped/full/窗口-操作手册-P071.png","caption":"窗口V4 P64-80｜第 71 页"},{"page":72,"title":"售票窗口-统计-冲红记录查看","body":"所有的冲红，都会生成冲红记录，以订单维度进行展示，可查看原支付类型，冲红后支付类型，；可以查看审核人和审核状态。","img":"assets/ppt-mapped/full/窗口-操作手册-P072.png","caption":"窗口V4 P64-80｜第 72 页"},{"page":73,"title":"售票窗口-统计-冲红记录查看","body":"在冲红记录或销售记录页点击查看，进入“订单详情”页后，如有冲红调整记录，在订单支付信息下方都；会有所有的冲红记录显示。","img":"assets/ppt-mapped/full/窗口-操作手册-P073.png","caption":"窗口V4 P64-80｜第 73 页"},{"page":75,"title":"售票窗口-安装打印机步骤","body":"安装该文件包：链接打印机应用包安装.exe；3.双击启动桌面上的这个应用 4.右下角出现这个图标，点击右；键，确认勾选了开机自启动；特别注意：这个图标必须每次开；机启动才可以驱动打印机，如不；能打印，请检查该图标，如无，；点击桌面上Printer APP 图标启动","img":"assets/ppt-mapped/full/窗口-操作手册-P075.png","caption":"窗口V4 P64-80｜第 75 页"},{"page":76,"title":"售票窗口功能操作说明","body":"安装身份证阅读器","img":"assets/ppt-mapped/full/窗口-操作手册-P076.png","caption":"窗口V4 P64-80｜第 76 页"},{"page":77,"title":"售票窗口-安装身份证阅读器步骤（精伦）","body":"1.确认自己电脑链接的是哪个品牌的身份证阅读器,(精伦或华视)；2.如为精伦，请安装《精论阅读器安装包 》这个安装包","img":"assets/ppt-mapped/full/窗口-操作手册-P077.png","caption":"窗口V4 P64-80｜第 77 页"},{"page":78,"title":"售票窗口-安装身份证阅读器步骤（华视）","body":"1.确认自己电脑链接的是哪个品牌的身份证阅读器,(精伦或华视)；3.如为华视，请安装《华视电子读卡服务》这个安装包","img":"assets/ppt-mapped/full/窗口-操作手册-P078.png","caption":"窗口V4 P64-80｜第 78 页"},{"page":79,"title":"售票窗口-安装身份证阅读器步骤","body":"目前同一台电脑不支持同时使用精伦和华视读卡器!","img":"assets/ppt-mapped/full/窗口-操作手册-P079.png","caption":"窗口V4 P64-80｜第 79 页"}]},{"title":"窗口套票售卖与退票","source":"窗口套票V5 P1-31","steps":[{"page":1,"title":"呀诺达-程票票票务系统","body":"换票流程优化专项说明与操作手册；2026/3/31","img":"assets/ppt-mapped/full/窗口-套票-P001.png","caption":"窗口套票V5 P1-31｜第 1 页"},{"page":2,"title":"窗口换票流程优化专项","body":"背景和目标","img":"assets/ppt-mapped/full/窗口-套票-P002.png","caption":"窗口套票V5 P1-31｜第 2 页"},{"page":7,"title":"窗口换票流程优化专项","body":"涉及部门和配置流程说明","img":"assets/ppt-mapped/full/窗口-套票-P007.png","caption":"窗口套票V5 P1-31｜第 7 页"},{"page":8,"title":"各部门职责和配置流程","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-套票-P008.png","caption":"窗口套票V5 P1-31｜第 8 页"},{"page":10,"title":"已通知配置完套票的直连渠道-散客下单","body":"OT A下的2大1小或者1大1小类套票，按所配置的套票自动拆分为3个子票，并自动匹配符合年龄要求的门票。点击“套票”文字可以弹出查看套票名称和编码；如游客未带身份证，直接可以从取票界面录入购票人手机号查询订单，进行取票，带证可直接入园，且3个子票全部在一个线上订单中。；目前官网小程序已支持 套票票号结构：；XXXX-CT – 代表了套票的主票号，所有OT A由于只设；置1张票，所以在OTA上的游客券码都为此票号；例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号；子票号后面会有&+编号 例：主票号&编号","img":"assets/ppt-mapped/full/窗口-套票-P010.png","caption":"窗口套票V5 P1-31｜第 10 页"},{"page":11,"title":"已通知配置完套票非直连渠道-散客下单","body":"1.OT A套票上线后，自上线日开始，线上用户下单的套票先进“线上票确认”页，通过游客购票手机号查询，如能查到，检查游客证件号是否填写；2.如未填写完整，请务必点击“补录”补充完整，再点击“确认”按钮，通过验证，如此操作后游客方可刷证入园！不确认未录证件的游客无法刷证入园！；3.目前暂时未控制不录证无法点击确认，即如不录证可出纸质票，游客凭纸质票依然可入园！请人工控制干预，做好规范。；4.录入证件会做校验，如游客重复购票，请先退票后再补录，建议不补录完不要给游客确认！年龄会自动校验录错会提示，2大1小的套票有价格的票为儿童票。","img":"assets/ppt-mapped/full/窗口-套票-P011.png","caption":"窗口套票V5 P1-31｜第 11 页"},{"page":12,"title":"已通知配置完套票非直连渠道-散客下单","body":"如在取票窗口，线上套票未录证件，不先操作线上票确认，无法打印套未录证件/未确认的套票子票，游客也不能直接入园！；在此处补录也没用，必须要去线上票确认窗口确认！","img":"assets/ppt-mapped/full/窗口-套票-P012.png","caption":"窗口套票V5 P1-31｜第 12 页"},{"page":14,"title":"套票现场售卖","body":"目前套票仅支持散客售票，可选择套票标签，选择了一个套票，自动生成所有子票，自动计算价格。；套票的库存数量可售卖数，按子票中最低库存量售卖；套票数量调整后，所有子票数量自动调整，价格自动计算；如套票中有组合票配置为现场销售，则与常规组合票一样；会出现场销售选择，操作同组合票，销售记录到票维度，；如要统计人数，建议子票同样设置为现场销售","img":"assets/ppt-mapped/full/窗口-套票-P014.png","caption":"窗口套票V5 P1-31｜第 14 页"},{"page":15,"title":"套票现场售卖","body":"套票支付确认时，显示所有套票购买的子票明细，2大1小套票购买2张，即4张成人票，2张儿童票，如限定年龄，主票为儿童票，即子票4张，主票2张。；套票一人一票按其内子票分别打印，一票多人即按票型打印","img":"assets/ppt-mapped/full/窗口-套票-P015.png","caption":"窗口套票V5 P1-31｜第 15 页"},{"page":16,"title":"套票查询","body":"套票票号结构：；XXXX-CT – 代表了套票的主票号，所有OT A由于只设置1张票，所以在OTA上的游客券码都为此票号 例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号，子票号后面会有&+编号 例：主票号&编号","img":"assets/ppt-mapped/full/窗口-套票-P016.png","caption":"窗口套票V5 P1-31｜第 16 页"},{"page":17,"title":"查看套票订单","body":"所有是套票类的门票，在订单详情中都会在门票名称前标注“套票”，点击“套票”可弹框查看套票名称和套票编码。；目前套票的打印序号保持了原来订单的打印序号处理，即按每个票型进行打印序号编码，但排序上，目前会先按套票排序显示，一家人的票需要在一起，然后再按；门票名称打印序号排序","img":"assets/ppt-mapped/full/窗口-套票-P017.png","caption":"窗口套票V5 P1-31｜第 17 页"},{"page":19,"title":"套票退票 – 窗口售卖 – 全部未检","body":"所有子票全部未检票的套票，可在“售票窗口-退票-正常退票”中全部操作正常退票，套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/窗口-套票-P019.png","caption":"窗口套票V5 P1-31｜第 19 页"},{"page":20,"title":"套票退票 – 窗口售卖 – 部分检票","body":"如套票中有部分票已检票，正常退票只能退未检票部分，已检部分必须强退申请，套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/窗口-套票-P020.png","caption":"窗口套票V5 P1-31｜第 20 页"},{"page":21,"title":"套票退票 – 窗口售卖 – 全部检票","body":"所有子票全部已检票的套票，可在“售票窗口-退票-强退申请”中全部操作强制退票，套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/窗口-套票-P021.png","caption":"窗口套票V5 P1-31｜第 21 页"},{"page":22,"title":"套票退票 – 线上预订票– 全部未检","body":"线上预订票只要子票全部还未检，即可从线上渠道申请退票，申请后，票务系统自动将全部未检子票退票","img":"assets/ppt-mapped/full/窗口-套票-P022.png","caption":"窗口套票V5 P1-31｜第 22 页"},{"page":23,"title":"套票退票 –线上预订票– 部分检票","body":"如套票中有部分票已检票，先将所有未检子票全部检票后，再在“PC后台-订单中心-散客订单管理-订单详情页-批量强退”中全部操作强制退票；套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上。","img":"assets/ppt-mapped/full/窗口-套票-P023.png","caption":"窗口套票V5 P1-31｜第 23 页"},{"page":24,"title":"套票退票 – 线上预订票 – 全部检票","body":"所有子票全部已检票的套票，可在“PC后台-订单中心-散客订单管理-订单详情页-批量强退”中全部操作强制退票；套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/窗口-套票-P024.png","caption":"窗口套票V5 P1-31｜第 24 页"},{"page":26,"title":"报表功能说明","body":"新套票报表与历史报表区别如下：；1.在“散客订单-线上预订-对帐明细导出”报表中，增加了套票名称和套票编码，如该子票是套票的打包票型，会标注出对应套票的名称和编码，通过套票名称和编；码可以过滤查看对应套票的订单和门票明细情况。；2.所有其他报表，线上预订的套票，如套票中有任一子票被检票，在所有报表中，所有子票都会按已检票维度统计，可能实际该子票还未被检票。检票数可能会与收；银对帐及所有相关财务对帐报表张数不一致，子票不检票，不会影响结算，但会影响入园人数统计。；3.原子票销售渠道为售票窗口，套票上线后，所有线上套票打包的子票，销售渠道全部为对应OT A分销商。","img":"assets/ppt-mapped/full/窗口-套票-P026.png","caption":"窗口套票V5 P1-31｜第 26 页"},{"page":27,"title":"其他问题说明","body":"团队预约票下单后无法转线下签单怎么办？","img":"assets/ppt-mapped/full/窗口-套票-P027.png","caption":"窗口套票V5 P1-31｜第 27 页"},{"page":28,"title":"团队预约票下单后无法转线下签单怎么办？","body":"如团队预约订单，导游想更换门票，走线下签单，首先，先“一键确认”","img":"assets/ppt-mapped/full/窗口-套票-P028.png","caption":"窗口套票V5 P1-31｜第 28 页"},{"page":29,"title":"团队预约票下单后无法转线下签单怎么办？","body":"在“团队管理-线上退票确认”页面，查到该笔订单，点击“退票确认”","img":"assets/ppt-mapped/full/窗口-套票-P029.png","caption":"窗口套票V5 P1-31｜第 29 页"},{"page":30,"title":"团队预约票下单后无法转线下签单怎么办？","body":"进入“线上退票详情页”，点击“退票确认”按钮，将刚下单成功的所有票全部操作退票。此时就可以线下签单出票了！","img":"assets/ppt-mapped/full/窗口-套票-P030.png","caption":"窗口套票V5 P1-31｜第 30 页"}]},{"title":"套票在售票窗口的操作","source":"套票全流程培训","steps":[{"page":13,"title":"套票管理配置– 总库存模式","body":"套票实名制要求主要根据现有OTA接入情况配置，如已直连OTA的，且OTA支持一票多人场景的，可配置“所有游客需填写身份证信息”，如此设置，OTA订单或窗口售；票如未将游客信息全部填写，下单会报错。如OTA还未直连或OTA不支持一票多人场景的，需配置为“需提供一位取票人身份信息”，此时订单中只需要有一位游客证件；信息即可。选择完成所需套票子票后，关注下“已选票数和套票总价”是否正确，再点击下一步。；本阶段，除“官网小程序”上使用的套票，可选择“所有游客需填；写身份信息”外，其余全部选择“需提供一位取票人身份信息”，；如官网小程序与其他OTA共用票型，想都使用套票自动拆单，则需；要拆分2种套票票型，不可共用。；确认好已选票数和套票价格后，点击“下一步”；套票总价=所有子票售卖价*子票1售卖数量+子票2售卖价*子票2；售卖数量+……；取消勾选即删除；此按钮为删除子票；选择套票实名制要求4；5","img":"assets/ppt-mapped/full/套票-全流程-P013.png","caption":"套票全流程培训｜第 13 页"},{"page":14,"title":"套票管理配置– 总库存模式","body":"此页面主要校验套票子票中必须一致的预订规则和库存， “是否实名/验证信息/预订限制/性别限制/启用年龄限制是否允许其他证件导入/生日限制”这些预订规则必须一；致；年龄和区域，可不一致，最终年龄按并集进行判断处理。；如套票为日历库存，需要进行每个组合票的日历库存校验，库存>0的日期必须一致。如套票为总库存，不校验一致性，但如有套票子票库存为0此处会提示，但允许保存。；库存为0的套票可以上架，但下单会失败。如该套票“需提供一位取票人身份证”，所选组合票必须有一张为实名制；如该套票“所有游客需要填写身份证”，如所选组合；票必须全部实名","img":"assets/ppt-mapped/full/套票-全流程-P014.png","caption":"套票全流程培训｜第 14 页"},{"page":15,"title":"套票配置举例 – 总库存模式","body":"以目前2大1小套票为例可按如下配置：；消费规则、退改规则，库存模式（目前由于缆车问题，含缆的都是总库存模式）全部配置一致; 售卖日期注意截止日期必须一致，开始日期，在当日后必须一致，在当日前，；开始日期以当日开始算; 官网小程序实名制选择“所有游客填写身份信息”，其他可选择“需提供一位取票人身份信息”；由于目前主票配置了套票总价，子票为0，所以；建议1张票的设置为儿童票，年龄段配置儿童，使用现有的OTA主票类组合票，2张票的设置为成人，年龄段配置成人，使用目前子票类。OTA下单时无此限制可随意，系；统自动匹配。","img":"assets/ppt-mapped/full/套票-全流程-P015.png","caption":"套票全流程培训｜第 15 页"},{"page":16,"title":"套票配置举例 – 总库存模式","body":"以目前2大1小套票为例可按如下配置：；注意预订规则：是否实名/验证信息/预订限制/性别限制/启用年龄限制是否允许其他证件导入/生日限制 这些规则配置一致；其他OTA：“需提供一位取票人身份证”，所选组合票必须有一张为实名制；官网小程序：“所有游客需要填写身份证”，如所选组合票必须全部实名","img":"assets/ppt-mapped/full/套票-全流程-P016.png","caption":"套票全流程培训｜第 16 页"},{"page":29,"title":"套票现场售卖","body":"目前套票仅支持散客售票，可选择套票标签，选择了一个套票，自动生成所有子票，自动计算价格。；套票的库存数量可售卖数，按子票中最低库存量售卖；套票数量调整后，所有子票数量自动调整，价格自动计算；如套票中有组合票配置为现场销售，则与常规组合票一样；会出现场销售选择，操作同组合票，销售记录到票维度，；如要统计人数，建议子票同样设置为现场销售","img":"assets/ppt-mapped/full/套票-全流程-P029.png","caption":"套票全流程培训｜第 29 页"},{"page":34,"title":"已通知配置完套票的直连渠道-散客下单","body":"OTA下的2大1小或者1大1小类套票，按所配置的套票自动拆分为3个子票，并自动匹配符合年龄要求的门票。点击“套票”文字可以弹出查看套票名称和编码；如游客未带身份证，直接可以从取票界面录入购票人手机号查询订单，进行取票，带证可直接入园，且3个子票全部在一个线上订单中。；目前官网小程序已支持","img":"assets/ppt-mapped/full/套票-全流程-P034.png","caption":"套票全流程培训｜第 34 页"},{"page":35,"title":"已通知配置完套票非直连渠道-散客下单","body":"1.OTA套票上线后，自上线日开始，线上用户下单的套票先进“线上票确认”页，通过游客购票手机号查询，如能查到，检查游客证件号是否填写；2.如未填写完整，请务必点击“补录”补充完整，再点击“确认”按钮，通过验证，如此操作后游客方可刷证入园！不确认未录证件的游客无法刷证入园！；3.目前暂时未控制不录证无法点击确认，即如不录证可出纸质票，游客凭纸质票依然可入园！请人工控制干预，做好规范。；4.录入证件会做校验，如游客重复购票，请先退票后再补录，建议不补录完不要给游客确认！年龄会自动校验录错会提示，2大1小的套票有价格的票为儿童票。","img":"assets/ppt-mapped/full/套票-全流程-P035.png","caption":"套票全流程培训｜第 35 页"},{"page":36,"title":"已通知配置完套票非直连渠道-散客下单","body":"如在取票窗口，线上套票未录证件，不先操作线上票确认，无法打印套未录证件/未确认的套票子票，游客也不能直接入园！；在此处补录也没用，必须要去线上票确认窗口确认！","img":"assets/ppt-mapped/full/套票-全流程-P036.png","caption":"套票全流程培训｜第 36 页"},{"page":40,"title":"套票配置注意事项：","body":"1. 所有打包套票的子票，消费规则，退改规则必须一致，规则中内容可以在规则配置中一次性修改，如子票需要更换所配的规则，套票必须下架后才能变更。；2. 所有打包套票的子票，库存模式与售卖时间必须一致；（1）总库存模式下，所有子票售卖开始日期在当日之前的，该套票售卖开始日期按当日算；（2）总库存模式下，套票中有子票售卖开始日期在当日当之后的，所有子票的售卖开始日期必须一致；（3）售卖日期截止日期必须一致；（4）日历库存模式下，所有日历库存日历时间必须一致。；3.所有打包套票的预订规则，除了年龄限制和区域限制取并集，其他规则配置必须一致，如子票需要更换所配的规则，套票必须下架后才能变更。；4.如套票要延期，该套票的所有子票售卖截止日期可以统一一次性配置，但如调整了售卖日期，对应所有子票如有缆车项目，将触发索道方的审核。；5.申请套票时必须告知票库该套票的实名制要求,该配置在套票维度，配置必须与OTA中对应配置一致，不一致下单会失败；（1）无需实名 – 即非实名制票；（2）需提供一位取票人身份信息 – 即一票填写一位游客信息；（3）所有游客需填写身份信息 - 即一张票需X位游客信息，X根据套票实际人数配置、；6. 套票需要配置主票，短信如不配置套票模板，会按主票维度发送；7. 现套票的子票无任何年龄限制，但如后续需要OTA可以进行年龄下单限制，无论主票子票，都必须要做年龄的预订规则设置；如2大1小，主票 1张 599元，年龄需要设置为儿童 ；子票 2张 0元，年龄需要设置为成人；哪些为成人票哪些为儿童票必须与收银沟通清楚，便于收银补录时快速识别；如配置了年龄限制，所有共用渠道的票型必须一并配置成套票并上线，否则影响现有票型的出票；8. 所有子票依然可以单独售卖。","img":"assets/ppt-mapped/full/套票-全流程-P040.png","caption":"套票全流程培训｜第 40 页"},{"page":44,"title":"全域-散客票配置","body":"预订规则中特别注意：所有套票改完编码后必须要调整此处预订规则，按套票张数配置预订信息；1.预订信息中如套票必须要求录入所有游客信息，请务必选择“每一张券需要X位游客信息”,套票打包了几张票，即填写几位游客，2大1小票，X=3；2.如此处预订信息中配置了需要多位游客信息，请务必确认在票务系统中配置的套票实名制要求必须一致，否则下单会报错！；3.预订信息中目前如选择“需要所有游客”的，实际上是一人一票，代表了仅提供一位游客信息。；4.目前套票如购买多张，游客信息将会随机拆分入不同套票，无法确保一个家庭人员共用一张套票，为规避退票问题，建议2种方案；（1）限制如购买套票（系统自动识别编码格式，判断是否为套票），小程序端一次仅能购一张套票，如多家庭购买，建议拆分多次下单。-- 目前系统默认使用此种方式，；（2）整单退票重新购票。；票务系统-套票打包规则配置 全域配置信息；游客下单报错","img":"assets/ppt-mapped/full/套票-全流程-P044.png","caption":"套票全流程培训｜第 44 页"},{"page":47,"title":"全域-官网小程序散客 – 身份证重购验证和年龄校验","body":"特别注意：；对于套票游客年龄的校验，原来在票务系统中由于只对应一张票，所以无；法在一张票上控制年龄段，做法是在OTA进行年龄限制，但无法确保2大1；小类套票一一对应游客年龄校验，现如需要做校验，可去除OTA中的年龄；限制，在票务系统中，配置套票主票和子票，各自设置对应年龄段，成人；或儿童；如：；儿童配置年龄限制后设置为主票，1张，599元；成人配置年龄限制后设置为子票，2张，0元；这样的3张票打包成套票后，OTA下单时自动校验，游客和票型自动匹配；但需要注意，如此配置；1.主票和子票就必须限定年龄，如部分历史票后续还会走窗口售票流程，；单子票会单独进行窗口换票售卖，收银后续需要对应年龄进行出票，需要；传达清晰。；2.如渠道共用票型，所有共用票型的渠道必须同步上套票，否则一旦限定；年龄，OTA就必须按该套票设定的年龄填写购票游客信息。；市场和票库务必对主票和子票对应的年龄提前约定清晰，同步到收银！","img":"assets/ppt-mapped/full/套票-全流程-P047.png","caption":"套票全流程培训｜第 47 页"},{"page":58,"title":"套票退票 – 窗口售卖 – 全部未检","body":"所有子票全部未检票的套票，可在“售票窗口-退票-正常退票”中全部操作正常退票，套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/套票-全流程-P058.png","caption":"套票全流程培训｜第 58 页"},{"page":59,"title":"套票退票 – 窗口售卖 – 部分检票","body":"如套票中有部分票已检票，正常退票只能退未检票部分，已检部分必须强退申请，套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/套票-全流程-P059.png","caption":"套票全流程培训｜第 59 页"},{"page":60,"title":"套票退票 – 窗口售卖 – 全部检票","body":"所有子票全部已检票的套票，可在“售票窗口-退票-强退申请”中全部操作强制退票，套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/套票-全流程-P060.png","caption":"套票全流程培训｜第 60 页"},{"page":61,"title":"套票退票 – 线上预订票– 全部未检","body":"线上预订票只要子票全部还未检，即可从线上渠道申请退票，申请后，票务系统自动将全部未检子票退票","img":"assets/ppt-mapped/full/套票-全流程-P061.png","caption":"套票全流程培训｜第 61 页"},{"page":62,"title":"套票退票 –线上预订票– 部分检票","body":"如套票中有部分票已检票，先将所有未检子票全部检票后，再在“PC后台-订单中心-散客订单管理-订单详情页-批量强退”中全部操作强制退票；套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上。","img":"assets/ppt-mapped/full/套票-全流程-P062.png","caption":"套票全流程培训｜第 62 页"},{"page":63,"title":"套票退票 – 线上预订票 – 全部检票","body":"所有子票全部已检票的套票，可在“PC后台-订单中心-散客订单管理-订单详情页-批量强退”中全部操作强制退票；套票建议必须保证所有票都必须全部退票，否则报表统计主票和子票数会对不上","img":"assets/ppt-mapped/full/套票-全流程-P063.png","caption":"套票全流程培训｜第 63 页"}]}]},{"id":"order","label":"订单与售后人员","title":"订单、门票、售后与冲红审核","desc":"从订单定位到单票，完成售后申请、审核与结果回查。","tasks":[{"title":"订单中心","source":"后台培训P70-80","steps":[{"page":71,"title":"订单中心-散客订单管理","body":"点击“+”号展开订单；点击“-”号折叠订单；门票显示：【价格类型】门票名称1（票型种类）季节类型；线上/线下订单查询由此处标签区分","img":"assets/ppt-mapped/full/后台-订单售后-P071.png","caption":"后台培训P70-80｜第 71 页"},{"page":72,"title":"订单中心-团队订单管理","body":"点击“+”号展开订单；点击“-”号折叠订单；门票显示：【价格类型】门票名称1（票型种类）季节类型；线上/线下订单查询由此处标签区分","img":"assets/ppt-mapped/full/后台-订单售后-P072.png","caption":"后台培训P70-80｜第 72 页"},{"page":73,"title":"订单中心-订单详情","body":"散客窗口购票如有大门票，随；机赋值一位游客购票人:散客线；上预订，传入购票人信息；团队窗口购票，购票人为外导；团队线上预订，购票人也为外；导，多导游随机赋值一位导游；线下窗口为下单当天；散客线上日历票为游客选择日期，；期票为门票有效期开始日期；团队线上为导游窗口确认的日期；外部平台订单号；团队订单才显示团队信息，散客订单无此信息","img":"assets/ppt-mapped/full/后台-订单售后-P073.png","caption":"后台培训P70-80｜第 73 页"},{"page":74,"title":"订单中心-订单详情","body":"该订单所有门票详细情况；该订单下所有未检票数 该订单下所有已退票数；该订单下所有游客信息；如已检票，且已开通了后台的申请强退功能；可以在此处对已检票发起批量强退申请；该订单下所有已检票数","img":"assets/ppt-mapped/full/后台-订单售后-P074.png","caption":"后台培训P70-80｜第 74 页"},{"page":75,"title":"订单中心-订单详情","body":"点击“门票名称”弹出该门票下单；时存储的“预订/消费/退改规则”；快照数据，所有检票和预订规则可；以进行查看","img":"assets/ppt-mapped/full/后台-订单售后-P075.png","caption":"后台培训P70-80｜第 75 页"},{"page":76,"title":"订单中心-订单详情","body":"点击每个游客门票后的“查看”弹；出该门票取票和检票详细信息","img":"assets/ppt-mapped/full/后台-订单售后-P076.png","caption":"后台培训P70-80｜第 76 页"},{"page":77,"title":"订单中心-订单详情","body":"如订单中有退票，在订单详情页的“售后订单”中，会展示所有该订单的售后单；选择“售后单”，下方可展示所选售后单的详细退票情况","img":"assets/ppt-mapped/full/后台-订单售后-P077.png","caption":"后台培训P70-80｜第 77 页"},{"page":78,"title":"订单中心-门票管理","body":"点击“查看”进入门票详情页","img":"assets/ppt-mapped/full/后台-订单售后-P078.png","caption":"后台培训P70-80｜第 78 页"},{"page":79,"title":"订单中心-门票详情","body":"门票详情页与订单详情页的区别之一就是订；单中游客门票详情显示所有门票，门票详情；页中游客门票详情仅会显示当前单张门票 其次，由于显示单门票，所以在门票详情页；会直接显示该门票的确认，取票和检票信息","img":"assets/ppt-mapped/full/后台-订单售后-P079.png","caption":"后台培训P70-80｜第 79 页"},{"page":80,"title":"订单中心 – 取票记录","body":"所有窗口的取票记录，都可以在后台此菜单中查看，每取一次记录一次取票记录","img":"assets/ppt-mapped/full/后台-订单售后-P080.png","caption":"后台培训P70-80｜第 80 页"}]},{"title":"售后中心与强制退票","source":"后台培训P81-90","steps":[{"page":82,"title":"散客退票流程","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-订单售后-P082.png","caption":"后台培训P81-90｜第 82 页"},{"page":83,"title":"团队退票流程","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-订单售后-P083.png","caption":"后台培训P81-90｜第 83 页"},{"page":84,"title":"系统后台-强制退票申请","body":"票务系统后台申请强制退票，需要从“订单中心”进入，找到对应订单，点击查看，进入“订单详情页”","img":"assets/ppt-mapped/full/后台-订单售后-P084.png","caption":"后台培训P81-90｜第 84 页"},{"page":85,"title":"系统后台-强制退票申请","body":"订单详情页中，找到游客/门票详情列；勾选中需要强退的门票，点；击批量强退可以批量申请；单票强退，可在点击该门票；后的申请强退按钮","img":"assets/ppt-mapped/full/后台-订单售后-P085.png","caption":"后台培训P81-90｜第 85 页"},{"page":86,"title":"系统后台-强制退票申请","body":"点击“申请强退”或“批量强退”按钮弹出“退票详情”对话框；窗口出售的门票，系统后台；申请强退，需要在此确认由；哪个窗口做最后的退票确认，；领导审核完成后，该窗口需；要做最后的退票确认！","img":"assets/ppt-mapped/full/后台-订单售后-P086.png","caption":"后台培训P81-90｜第 86 页"},{"page":87,"title":"散客/团队强制退票审核 – 同意","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-订单售后-P087.png","caption":"后台培训P81-90｜第 87 页"},{"page":88,"title":"散客/团队强制退票审核 – 驳回","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-订单售后-P088.png","caption":"后台培训P81-90｜第 88 页"},{"page":89,"title":"售后中心-散客/团队售后订单查询","body":"所有退票，都可以在售后中心查询，每个订单可以多次退票，每次退票生成一个售后单；可以通过确认是散客退票还是团队退；票选择不同的菜单查看；这两个菜单仅是做为退票查询，退票；申请在售票窗口以及在后台“票务中；心-散客/团队订单查询页中”，只要；有权限，可以在对应订单详情页进行；申请；进入功能页面后，选择是什么类型的退票，；正常退票还是强制退票，所有符合退票条件；的都为正常退票，所有不符合退票条件的及；已检票都属于强制退票。","img":"assets/ppt-mapped/full/后台-订单售后-P089.png","caption":"后台培训P81-90｜第 89 页"},{"page":90,"title":"订单中心-订单详情","body":"从售后中心进入“订单详情”，系统自动定位到该售后单上；选择当前“售后单”，下方展示所选售后单的详细退票情况","img":"assets/ppt-mapped/full/后台-订单售后-P090.png","caption":"后台培训P81-90｜第 90 页"}]},{"title":"冲红审核","source":"后台培训P178-181","steps":[{"page":178,"title":"冲红管理","body":"（售票员）","img":"assets/ppt-mapped/full/后台-团队冲红-P178.png","caption":"后台培训P178-181｜第 178 页"},{"page":179,"title":"售票窗口-统计-冲红审核","body":"冲红需要在票务系统后台-冲红管理-冲红审核菜单 – 待审批中进行审核","img":"assets/ppt-mapped/full/后台-团队冲红-P179.png","caption":"后台培训P178-181｜第 179 页"},{"page":180,"title":"售票窗口-统计-冲红审核 – 同意","body":"特别说明：如冲红功能从现金类支付方式调整到预付款或签单 ，在审核时也会 判断旅行社的账户余额或授信额度是否足够 ，如不够，提交会；提示余额不足，需要联系预订部进行充值后才可进行冲红。；完成冲红是以审核通过为最终节点的，如未审核或审核驳回，该订单的支付方式不变。","img":"assets/ppt-mapped/full/后台-团队冲红-P180.png","caption":"后台培训P178-181｜第 180 页"},{"page":181,"title":"售票窗口-统计-冲红审核 – 驳回","body":"完成冲红是以审核通过为最终节点的，如未审核或审核驳回，该订单的支付方式不变。","img":"assets/ppt-mapped/full/后台-团队冲红-P181.png","caption":"后台培训P178-181｜第 181 页"}]}]},{"id":"team","label":"预订部 / 团队岗位","title":"旅行社、导游、团队政策和预约","desc":"维护团队基础资料、政策、预约、审批、财务和窗口确认。","tasks":[{"title":"团队管理配置与预约","source":"后台培训P91-155","steps":[{"page":92,"title":"团队管理配置与预订/入园流程","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-团队冲红-P092.png","caption":"后台培训P91-155｜第 92 页"},{"page":93,"title":"基础信息功能简介与配置流程","body":"旅行社管理：用以配置所有集团、旅行社基本信息，账户以及预约来源，预约规则等；导游管理：用以新增/编辑/导入所有导游信息；团队票管理：用以配置所有团队门票的政策、线上预约票导游增购和自助退款的设置；门票政策管理：用以配置门票相关政策并关联对应门票和旅行社；预订配置说明：用以给使用团队线上预约平台下单的旅行社查看相关景区门票和预订政策。；团队预约订单：用以窗口售票员查询预约单，一键确认生成团队订单；超限审批：用以领导审核和查看所有超限团队订单（人数或预约时间超预订限制）；团队预约报备：暂时不启用。；线上退票确认：展示所有团队线上预约单，只要有还未检票的订单，此功能中支持一键正常退票；线上退票查询：用以查询所有线上团票退票的订单和退票详情。；财务管理-旅行社账户管理：用以查看和管理各旅行社账户余额和授信信息；财务管理-集团账户管理：用以查看和管理各集团账户余额和授信信息；财务管理-充值申请：用以查看各账户所有的充值记录并支持各账户充值申请；财务管理-充值审核：用以审核各账户充值申请；财务管理-资金流水：用以查看各账户资金流水信息","img":"assets/ppt-mapped/full/后台-团队冲红-P093.png","caption":"后台培训P91-155｜第 93 页"},{"page":94,"title":"团队管理","body":"团队类型和预订规则配置；（预订部）","img":"assets/ppt-mapped/full/后台-团队冲红-P094.png","caption":"后台培训P91-155｜第 94 页"},{"page":95,"title":"团队管理-团队类型管理","body":"团队类型主要用来区分各旅行社带的团队类型，也可以通过 不同的团队类型进行预约规则的管理 ，在此设置的预约规则（人数/时间）的限；定，如对应旅行社的预约规则是启用的情况下，就会生效。；如使用景区线上预约平台下单的旅行社，下单时需要选择当前团队类型，系统会 根据所选择的团队类型进行预约规则的判断；如是系统对接的旅行社，系统会根据大门票的团队类型 来判断该团队在下单时的预约规则。；提前购买的天数和时间必须同时设定，；这是旅行社最后下单时间的限制；最小人数为最小成团队数，超过限制按旅行；社设定的预约控制进行处理；最大人数为最大可下单人数，超出下不了预；约单和增购单此功能暂未启用，随便填写，无影响","img":"assets/ppt-mapped/full/后台-团队冲红-P095.png","caption":"后台培训P91-155｜第 95 页"},{"page":96,"title":"团队管理-旅行社管理","body":"（预订部）","img":"assets/ppt-mapped/full/后台-团队冲红-P096.png","caption":"后台培训P91-155｜第 96 页"},{"page":97,"title":"团队管理-旅行社管理","body":"“编辑”可以编辑旅行社相关配置；“查看配置”仅能查看旅行社相关配置；可查看该旅行社绑定的所有门票；新增集团或旅行社；旅行社启用和禁用，直接影响到售票窗口是否可以给此旅行社出票，或对接旅行社和线上团队预约平台中该旅行社是否可以登录或出票；对旅行社可以勾选后批量设置启用或禁用。","img":"assets/ppt-mapped/full/后台-团队冲红-P097.png","caption":"后台培训P91-155｜第 97 页"},{"page":98,"title":"团队管理-旅行社管理 – 添加集团","body":"添加旅行社前必须先添加旅行社所属集团，集团编码可自定义编写；集团的默认支持方式，主要是用来当该旅行社后续配置为使用 集团账号付款时 ，在此配置了默认的支付方式后，售票窗口在选择该旅行社时，；就会默认加载该集团的默认支付方式，无需要再做调整 便于窗口的处理，当然支付方式窗口可以做修改 。","img":"assets/ppt-mapped/full/后台-团队冲红-P098.png","caption":"后台培训P91-155｜第 98 页"},{"page":99,"title":"团队管理-旅行社管理 – 添加旅行社-基础信息","body":"添加旅行社前必须先添加旅行社所属集团，集团编码可自定义编写；集团的默认支持方式，主要是用来当该旅行社后续配置为使用 集团账号付款时，在此配置了默认的支付方式后，售票窗口在选择该旅行社时，；就会默认加载该集团的默认支付方式，无需要再做调整 便于窗口的处理，当然支付方式窗口可以做修改 。","img":"assets/ppt-mapped/full/后台-团队冲红-P099.png","caption":"后台培训P91-155｜第 99 页"},{"page":100,"title":"团队管理-旅行社管理 – 添加旅行社 – 预约规则","body":"添加完成旅行社“基础信息”后，需要配置该旅行社的 “预约规则”；预约来源：；（1）无预约（所有走线下窗口售票的旅行社，无需配置预约规则）；（2）系统对接（所有与旅行社系统对接 ，走线上预约的社）；（3）线上预约平台（所有使用团队线上预约平台 下单的旅行社；目前为所有一日游旅行社，后期看业务推动情况）；（4）线上报备（此功能暂时不启用，不用配置）；预约规则：；（1）启用（开启成团人数和预约时间限制）；（2）禁用（无成团人数和预约时间限制）；默认进入时，管理员手机号，导游增购和导游查询 有效周期会显示，；但实际会根据选择的预约来源显示，如选择无预约和线上报表，这些；选项会隐藏，详细配置请查看PPT下一页。","img":"assets/ppt-mapped/full/后台-团队冲红-P100.png","caption":"后台培训P91-155｜第 100 页"},{"page":101,"title":"团队管理-旅行社管理 – 添加旅行社 – 预约规则","body":"预约来源系统对接+预约规则启用；（所有规则配置实时获取，后台变更后即可生效）；即：旅行社系统下单时会按景区设定的预约规则校验；1.下单时强控启用+超限审批启用/禁用；旅行社系统下单时就会拦截所有不符合预约规则的订单 ，会有出错提示；2. 下单时强控禁用+超限审批启用；旅行社系统下单时不会拦截不符合预约规则的订单，不会出错提示，；下单成功后，在售票窗口一键确认时会有超限提示，售票员可以发现超限；并提交申请，审批通过后才允许下单，否则不允许下单；3.下单时强控禁用+超限审批禁用；下单成功后，在售票窗口一键确认时会拦截订单，不能下单，；不能提交超限审核，卡单（实时调整为超限审批启用后不会卡单）；对接秘钥：未生成，点击生成秘钥自动生成，点击确认绑定到该社，点击“复制”复制秘钥，；如新增对接旅行社，需要将生成的秘钥发给对方 。；导游增购：确认该社是否开放让导游上小程序自行增购项目票（如一日游社可以填写否）；导游查询有效周期：导游的团期结束后几天内 可以进小程序查询订单，过期后将查询不到；目前默认与旅行社协议都是3天。","img":"assets/ppt-mapped/full/后台-团队冲红-P101.png","caption":"后台培训P91-155｜第 101 页"},{"page":102,"title":"团队管理-旅行社管理 – 添加旅行社 – 预约规则","body":"预约来源线上预约平台+预约规则启用；（所有规则配置实时获取，后台变更后即可生效）；即：景区提供的团队线上预约平台下单时 会按景区设定的预约规则校验；1.下单时强控启用+超限审批启用/禁用；在预约平台下单时就会拦截所有不符合预约规则的订单 ，会有出错提示；2. 下单时强控禁用+超限审批启用；在预约平台下单时不会拦截不符合预约规则的订单，不会出错提示，；下单成功后，即刻生成超限审批单；3.下单时强控禁用+超限审批禁用；下单成功后，不会自动生成超限审核，卡单（不可实时调整，慎用！！）；管理员手机号：配置该旅行社管理员手机号，配置完成后，系统会发送短信给对应管理员，建议；线下提供给对方《呀诺达团队线上预约系统操作手册 V2.0（一日游）》PPT；导游增购：确认该社是否开放让导游上小程序自行增购项目票（如一日游社可以填写否）；导游查询有效周期：导游的团期结束后几天内 可以进小程序查询订单，过期后将查询不到；目前默认与旅行社协议都是3天。","img":"assets/ppt-mapped/full/后台-团队冲红-P102.png","caption":"后台培训P91-155｜第 102 页"},{"page":103,"title":"票务中心-团队票/团队类型配置","body":"（票库）","img":"assets/ppt-mapped/full/后台-团队冲红-P103.png","caption":"后台培训P91-155｜第 103 页"},{"page":104,"title":"票务中心-组合票添加/编辑 – 票库添加","body":"当团散类型为“团队”时，票库添加组合票时需要确认“团队类型”，每；个票允许有多个团队类型，因为每个旅行社可以有多个政策，每个政策又；可以联调多个门票，所以每个旅行社的票型上配置了多个团队类型，最终；系统会获取到该旅行社所有票型对应的团队类型，针对后续该旅行社下单；时所选择的团队类型进行预约控制；如该旅行社在预约规则中“允许导游增购”，；在此处与该旅行社关联的门票“是否允许自助增购”为“是”，；在导游小程序增购页中才会显示该门票，；如选择“否”，即使旅行社允许导游增购，该门票也不会在增购选项中；是否允许自助退款，如选择“是”，导游小程序自动开启未检票自助退票；功能，如选择“否”，此功能不开放；每个票型的渠道逻辑，参考《样板：票型价格设置申请单（2025年4月新模板）》；渠道逻辑参考说明","img":"assets/ppt-mapped/full/后台-团队冲红-P104.png","caption":"后台培训P91-155｜第 104 页"},{"page":105,"title":"团队管理-团队票管理","body":"新增/配置门票策略；（预订部）","img":"assets/ppt-mapped/full/后台-团队冲红-P105.png","caption":"后台培训P91-155｜第 105 页"},{"page":106,"title":"团队管理-团队票管理 – 设置门票政策","body":"每个门票可以对应配置一种门票政策；每种门票政策可以配置多个旅行社和多个门票；旅行社与门票的绑定关系可以依靠门票政策建立；可查看详细门票配置信息；此处可对导游小程序上的；增购项目票的显示进排序；值越大，门票排序越靠前；必须勾选才可以点击门票政策；此处支持批量设置，每次勾选；后，设置完会覆盖前面的配置；门票、政策、旅行社关系；可以通过该导出页面进行；统一查看","img":"assets/ppt-mapped/full/后台-团队冲红-P106.png","caption":"后台培训P91-155｜第 106 页"},{"page":107,"title":"团队管理-团队票管理 – 设置导游增购与未检票退票功能","body":"必须勾选才可以点击导游；增购退款设置；此处支持批量设置，每次；勾选后，设置完会覆盖前；面的配置；如该旅行社在预约规则中“允许导游增购”，；在此处与该旅行社关联的门票“是否允许自助增购”为“是”，；在导游小程序增购页中才会显示该门票，；如选择“否”，即使旅行社允许导游增购，该门票也不会在增购选项中；是否允许自助退款，如选择“是”，导游小程序自动开启未检票自助退；票功能，如选择“否”，此功能不开放","img":"assets/ppt-mapped/full/后台-团队冲红-P107.png","caption":"后台培训P91-155｜第 107 页"},{"page":108,"title":"团队管理-门票政策管理","body":"政策关联旅行社/门票；（预订部）","img":"assets/ppt-mapped/full/后台-团队冲红-P108.png","caption":"后台培训P91-155｜第 108 页"},{"page":109,"title":"团队管理-门票政策管理-新增/编辑门票政策","body":"门票政策可以在门票政策管理里添加和编辑， 每个政策都可以对应多个门票和多个旅行社；各旅行社门票的上下架全部通过这个政策进行关联，如门票和旅行社 有关联关系，且是已上架状态，在售票窗口/线上团队预约平台/旅行社系统接；口中都会出现该门票，如无关联或已下架则不会出现也不能下单。；特别注意：目前与旅行社系统直接虽然会同步给对方门票价格信息，但 旅行社系统不直接使用我方门票价格 ，该门票信息仅会影响对方是否能选择；该门票下单和是否可售，价格需要线下协商确认，上架也需要单独通知，否则旅行社不能自动完成上架， 必须对方人工关联。；如政策有已关联门票，不允许删除，请先去除所有关联关系。","img":"assets/ppt-mapped/full/后台-团队冲红-P109.png","caption":"后台培训P91-155｜第 109 页"},{"page":110,"title":"团队管理-门票政策管理 – 关联旅行社","body":"某一政策可以批量关联不同旅行社，关联旅行社时，政策有对应门票即可同时将这些门票与旅行社关联；勾选多个旅行社，再点击；批量绑定或批量解绑，可；同时处理这个政策与这些；旅行社的绑定关系；点击单个旅行社后的“绑；定”或“解绑”按钮，则；处理单个社与这个政策的；绑定关系。","img":"assets/ppt-mapped/full/后台-团队冲红-P110.png","caption":"后台培训P91-155｜第 110 页"},{"page":112,"title":"团队管理-预订配置说明","body":"预订配置说明会显示在团队线上预约平台的每个旅行社-预约下单页面","img":"assets/ppt-mapped/full/后台-团队冲红-P112.png","caption":"后台培训P91-155｜第 112 页"},{"page":113,"title":"团队管理-超限审批","body":"（预订部）","img":"assets/ppt-mapped/full/后台-团队冲红-P113.png","caption":"后台培训P91-155｜第 113 页"},{"page":114,"title":"团队管理-超限审批","body":"1.“团队管理-超限审批” 进入审批列表；2. 查看“待审批”列表。已审批：所有已审批的超限单；已关闭：所有取消或还未审批又修改的超限单。","img":"assets/ppt-mapped/full/后台-团队冲红-P114.png","caption":"后台培训P91-155｜第 114 页"},{"page":115,"title":"团队管理-超限审批","body":"1. 点击列表页“详情”- 查看详细预约单详情，黄色标签部分为系统自动识别出来的超限内容，供参考。；2. 点击“同意/驳回”会弹出弹窗填写建议，确认后，窗口才能进行确认下单。","img":"assets/ppt-mapped/full/后台-团队冲红-P115.png","caption":"后台培训P91-155｜第 115 页"},{"page":116,"title":"售票员– 审批通过-一键确认","body":"1.在列表页点击“订单确认”进入详情页，2.如已审批通过，会显示“一键确认”，按原流程操作即可。；3.如还未通过，可以等通知，完成审批后，“刷新订单”；1；2；3","img":"assets/ppt-mapped/full/后台-团队冲红-P116.png","caption":"后台培训P91-155｜第 116 页"},{"page":117,"title":"售票员– 查看团队类型和超限审批","body":"1. 筛选条件下拉可选团队类型，目前只有常规团和一日游；2. 超限审批“有”，说明该团队不符合预订规则，需要领导审核，超限审批“无”，说明是正常一日游团，可以一键下单。；1 2","img":"assets/ppt-mapped/full/后台-团队冲红-P117.png","caption":"后台培训P91-155｜第 117 页"},{"page":118,"title":"一日游团政策规定与特别注意事项","body":"当前一日游政策规定；1.当天9点前下单，9点以后下单自动生成超限审批，待领导审核；2.最小成团人数>=10人，小于此数的团队，自动生成超限审批，待领导审核；一日游系统中暂时不要求旅行社填写行程单，所以系统中查不到行程单。；特别注意事项：；1.旅行社团队人数必须符合入园实际人数 （包含儿童、老人 ），不包含全陪导游或司兼导，；2.如发现预约单有游客现场新增，不能协助修改预约单，不能点一键确认，要求导游打电；话回社，让计调在预约平台中修改订单！（不管领导是否已审核，在一键确认前新增都可；要求重新修改）；3.如发现实际入园人数<团队预约人数，可以做记得汇报给预订部，后续系统也可以监测，；目前如实际入园人数<预约人数，自动与常规团一样会自动退票。；4.如有无证全陪导游，旅行社需要下订单，在“一键确认”前确认好，如发现问题及时要；求导游打电话回社让计调在预约平台中重新修改订单！；5.有特殊情况全部汇报预订部，是否可给导游增购或是否可走线下全部由预订部确认。；一日游暂时不开放项目票线上增购！；如项目增购走原线下流程购票！！；无需辅导导游登录小程序！","img":"assets/ppt-mapped/full/后台-团队冲红-P118.png","caption":"后台培训P91-155｜第 118 页"},{"page":119,"title":"团队管理-财务管理","body":"（预订部）","img":"assets/ppt-mapped/full/后台-团队冲红-P119.png","caption":"后台培训P91-155｜第 119 页"},{"page":120,"title":"团队管理– 财务管理 – 旅行社账户管理","body":"1. 如在新建旅行社时，确认该旅行社选择的 “付款账户类型” 的是“旅行社”，该社的预付款和签单都会在该旅行社账户中进行扣减；2. 每个旅行社只对应一个总账户，但总账户会能2个子账户分别记录是签单还是预付款付款，可以同时使用2个账户，到底使用哪个账户，在售票；时会加载旅行社中“默认支付方式”，但后续 售票员可以进行重新选择。如预付款没钱时，可以切换授信。；3.在此页面可以通过标签“授信管理”或“预付款管理” 切换实时查询每个旅行社的当前预付款余额 ，或授信额度，预付款永远为正数，<0后旅行；社窗口无法下单（包含线上线下），授信可以为负数。；每个旅行社“授信额度”或；“余额”只有一行，代表当前；总额度或余额","img":"assets/ppt-mapped/full/后台-团队冲红-P120.png","caption":"后台培训P91-155｜第 120 页"},{"page":121,"title":"团队管理– 财务管理 – 旅行社账户管理","body":"每个旅行社后，点击对应“充；值记录”和“资金流水”，会；跳转到“充值申请”和“资金；流水”页面，进入后页面会自；动查询该旅行社对应所有信息；授信限制启用主要用来确认；是否允许旅行社签单支付时授信负数；如禁用，则允许授信额度为负数；如启用，就会限制额度必须为正数","img":"assets/ppt-mapped/full/后台-团队冲红-P121.png","caption":"后台培训P91-155｜第 121 页"},{"page":122,"title":"团队管理– 财务管理 – 旅行社账户管理","body":"1. 如在新建旅行社时，确认该旅行社选择的 “付款账户类型” 的是“集团”，该社的预付款和签单都会在该集团账户中进行扣减；2. 每个集团只对应一个总账户，但总账户会能2个子账户分别记录是签单还是预付款付款，可以同时使用2个账户，到底使用哪个账户，在售票时；会加载旅行社中“默认支付方式”，但后续 售票员可以进行 重新选择。如预付款没钱时，可以切换授信。；3.在此页面可以通过标签“授信管理”或“预付款管理” 切换实时查询每个旅行社的当前预付款余额 ，或授信额度，预付款永远为正数，<0后旅行；社窗口无法下单（包含线上线下），授信可以为负数。；每个集团“授信额度”或“余；额”只有一行，代表当前总额；度或余额","img":"assets/ppt-mapped/full/后台-团队冲红-P122.png","caption":"后台培训P91-155｜第 122 页"},{"page":123,"title":"团队管理– 财务管理 – 集团账户管理","body":"每个集团后，点击对应“充值；记录”和“资金流水”，会跳；转到“充值申请”和“资金流；水”页面，进入后页面会自动；查询该集团对应所有信息；授信限制启用主要用来确认；是否允许集团账户签单支付时授信负数；如禁用，则允许授信额度为负数；如启用，就会限制额度必须为正数","img":"assets/ppt-mapped/full/后台-团队冲红-P123.png","caption":"后台培训P91-155｜第 123 页"},{"page":124,"title":"团队管理– 财务管理 – 充值申请","body":"充值功能可以为“集团”或“旅行社”充值，充值时可通过先切换标签页（旅行社 /集团），再点进“充值”按钮进行充值，；也可以随便点击后在弹出页面中选择充值账户类型， 请检查仔细当前旅行社使用的付款账户类型后再进行充值 ！；充值类型有“授信/余额”，授信对应签单（允许下单账户不受限制-负数），余额对应预付款（不允许下单账户为负数）；为了避免充值金额填写错误，在授信和余额充值时允许填写负数 ，可以进行抵消。","img":"assets/ppt-mapped/full/后台-团队冲红-P124.png","caption":"后台培训P91-155｜第 124 页"},{"page":125,"title":"团队管理– 财务管理 – 充值审核","body":"所有充值必须要经过审核，请进入“充值审核”页进行审核；“待审批”- 显示所有待审批的充值记录，只有审批通过账户才会真正充值 ，否则账户不会充值成功；“已审批”- 显示所有审批记录，包括驳回的记录","img":"assets/ppt-mapped/full/后台-团队冲红-P125.png","caption":"后台培训P91-155｜第 125 页"},{"page":126,"title":"团队管理– 财务管理 – 资金流水","body":"资金流水功能可以查询所有旅行社或集团使用签单或预付款的流水记录；里面包含了账户充值，消费(签单/预付门票下单-每条记录对应一笔门票订单)，退款（正常退票/强制退票-每条记录对应一笔门票售后单）；内导消费（签单/预付款内导下单- -每条记录对应一笔内导订单），内导退款（每条记录对应一笔内导售后单）","img":"assets/ppt-mapped/full/后台-团队冲红-P126.png","caption":"后台培训P91-155｜第 126 页"},{"page":127,"title":"团队线上预约平台操作说明","body":"（外部旅行社操作）","img":"assets/ppt-mapped/full/后台-团队冲红-P127.png","caption":"后台培训P91-155｜第 127 页"},{"page":128,"title":"团队线上预订全流程介绍","body":"02；旅行社-计调；下单；旅行社-导游/景区窗口；景区窗口验证+购买二销项目票；旅行社-导游/景区检票口；入园检票；旅行社-财务；线上核对预约订单报表","img":"assets/ppt-mapped/full/后台-团队冲红-P128.png","caption":"后台培训P91-155｜第 128 页"},{"page":129,"title":"团队线上预约平台","body":"管理员操作指引","img":"assets/ppt-mapped/full/后台-团队冲红-P129.png","caption":"后台培训P91-155｜第 129 页"},{"page":130,"title":"旅行社管理员-登录系统","body":"请收藏系统登录地址：https://teambooking.ly.com/；管理员首次登录；可以选择“短信登录”方式；通过手机号+验证码；登录”呀诺达-团队线上预约平台”；首次登录请选择“短信登录”","img":"assets/ppt-mapped/full/后台-团队冲红-P130.png","caption":"后台培训P91-155｜第 130 页"},{"page":131,"title":"旅行社管理员-登录系统","body":"1登录后，请点击界面右上方头像下的；“账号及密码”；2.修改用户昵称，账号或密码；3. 后续则可通过账号和密码进行系统登录；点击头像下方的“账号及密码”；1；2；3","img":"assets/ppt-mapped/full/后台-团队冲红-P131.png","caption":"后台培训P91-155｜第 131 页"},{"page":132,"title":"旅行社管理员-配置角色","body":"1. 选择“人员管理 – 角色管理”；菜单，打开角色管理功能界面，；可以查看当前系统所有操作角；色；2. 初次登录角色列表为空，可点；击“新增角色”按钮，自行增；加角色。；2；1","img":"assets/ppt-mapped/full/后台-团队冲红-P132.png","caption":"后台培训P91-155｜第 132 页"},{"page":133,"title":"旅行社管理员-配置角色","body":"1. 填写角色名称；2. 按所添加的角色，勾选允许该角色操作；的菜单权限；3. 点击“保存”，保存该角色的权限设置。；特别注意：；团队预约，团队订单，退票查询；可开给计调，进行提前预约下单、订单查询；操作等；财务管理-对帐报表菜单可给财务人员开，；方便对帐；人员管理下菜单“角色管理”，“员工管理”；请不要开放给计调，但导游管理请务必开放；给计调，用以新增导游信息！；2；1；3","img":"assets/ppt-mapped/full/后台-团队冲红-P133.png","caption":"后台培训P91-155｜第 133 页"},{"page":134,"title":"旅行社管理员-配置员工及角色权限","body":"1. 添加完成角色后，可以通过角；色管理列表页，查看，编辑和；删除相关角色；2. 确认角色无问题后，通过对应；角色后的“邀请员工”按钮，；添加员工；2；1","img":"assets/ppt-mapped/full/后台-团队冲红-P134.png","caption":"后台培训P91-155｜第 134 页"},{"page":135,"title":"旅行社管理员-配置员工及角色权限","body":"1. 点击对应角色后的“邀请员工”；按钮，弹出邀请员工对话框；2. 填写对应员工手机号进行注册；3. 添加完成后，该员工即可使用；该手机号进行登录。该员工操；作权限为对应角色配置的角色；菜单权限；2；1","img":"assets/ppt-mapped/full/后台-团队冲红-P135.png","caption":"后台培训P91-155｜第 135 页"},{"page":136,"title":"团队线上预约平台","body":"计调操作指引","img":"assets/ppt-mapped/full/后台-团队冲红-P136.png","caption":"后台培训P91-155｜第 136 页"},{"page":137,"title":"计调-登录系统","body":"请收藏系统登录地址：https://teambooking.ly.com/；首次登录；可以选择“短信登录”方式；通过手机号+验证码；登录”呀诺达-团队线上预约平；台”；如登录不了，；请确认旅行社管理员是否正确；添加了您的手机号。；首次登录请选择“短信登录”","img":"assets/ppt-mapped/full/后台-团队冲红-P137.png","caption":"后台培训P91-155｜第 137 页"},{"page":138,"title":"计调-登录系统","body":"1登录后，请点击界面右上方头像下的；“账号及密码”；2.修改用户昵称，账号或密码；3. 后续则可通过账号和密码进行系统登录；点击头像下方的“账号及密码”；3；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P138.png","caption":"后台培训P91-155｜第 138 页"},{"page":139,"title":"计调-新增导游","body":"1.点击“人员管理”- “导游管理”菜单，进入导游查询管理功能；2.该列表页为景区线上导游库中导游，一日游导游可能并不在库中，建议 新增或导入导游信息 。；1；2；3.可以通过“新增导游”和“批量导入导游” 来进行导游；信息添加。；4. 新增的导游和下单时选择的导游都会与当前旅行社进行；绑定，绑定后可以修改导游姓名和手机号。；5.未与旅行社社绑定的导游，暂不可修改信息，如您选择；的导游手机号有误，建议先下单成功，与旅行社建立绑定；管理后再到此界面进行修改，也可联系景区修改或让导游；到景区窗口修改。；3 3；4","img":"assets/ppt-mapped/full/后台-团队冲红-P139.png","caption":"后台培训P91-155｜第 139 页"},{"page":140,"title":"计调-新增导游","body":"1.点击“人员管理”- “导游管理”菜单，进入导游查询管理功能；2.该列表页为景区线上导游库中导游，一日游导游可能并不在库中，建议 新增或导入导游信息 。；1；2；3.可以通过“新增导游”和“批量导入导游” 来进行导游；信息添加。；4. 新增的导游和下单时选择的导游都会与当前旅行社进行；绑定，绑定后可以修改导游姓名和手机号。；5.未与旅行社社绑定的导游，暂不可修改信息，如您选择；的导游手机号有误，建议先下单成功，与旅行社建立绑定；管理后再到此界面进行修改，也可联系景区修改或让导游；到景区窗口修改。；3 3；4","img":"assets/ppt-mapped/full/后台-团队冲红-P140.png","caption":"后台培训P91-155｜第 140 页"},{"page":141,"title":"计调-批量新增导游","body":"1.点击“批量导入导游”弹出导入导游信息框，即可导入多个导游信息。；2.可以通过下载系统提供的“导入导游模板” ，按文件要求填写相关数据进行游客信息的导入，也可以将您ERP系统中游客信息导出 后，直接导入系；统，线上团队预约系统可以自动识别到导游姓名和身份证号，请 确保您ERP系统导出的数据中 有“导游姓名”和“导游身份证” 列。；3.将完整需要购票的游客Excel表信息准备好后，拖动至大框，系统自动识别并上传，如有问题，会在框中进行提示，必须要是 正确的身份证信息，；且不能重复。；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P141.png","caption":"后台培训P91-155｜第 141 页"},{"page":142,"title":"计调-单独新增导游","body":"1. 点击“新增导游”按钮 弹出导游信息录入框；2. 填写导游信息，*号为必填项，请务必准确填写导游的身份证号，否则导游不能刷证入园，身份证号录错也不能再修改，只能重新添加 ；手机号也；请准确，一般国内导游请填写身份证，国外导游填写护照；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P142.png","caption":"后台培训P91-155｜第 142 页"},{"page":143,"title":"计调-预约下单","body":"1.点击“订单管理”-“团队预约”菜单，进入预约下单界面；2.最上方为当前登录的旅行社名，请务必确认您登录的旅行社 准确无误。；3.请注意右侧提示的人数和提前预约时间规则,团队人数不满或超过提前预约时间,会触发景区特殊报备流程 ,需景区审核通过后导游方可入园.；4.预约日期为您所下单的团队预约的入园游玩日期；1；2；3；4","img":"assets/ppt-mapped/full/后台-团队冲红-P143.png","caption":"后台培训P91-155｜第 143 页"},{"page":144,"title":"计调-预约下单","body":"1. 团队人数必须符合最终入园人数，如与；最终实际入园人数不符，景区后续会做检；查核实。；2. 团期的默认起始时间为预约日期，结束；日期可以自由选择，为避免团队临时调整；时间，在此时间范围内，导游都可以带团；到窗口确认入园。；1 2","img":"assets/ppt-mapped/full/后台-团队冲红-P144.png","caption":"后台培训P91-155｜第 144 页"},{"page":145,"title":"计调-预约下单","body":"1.选择导游选项框，可以输入导游姓名，系；统会自动下拉展示所有系统库中已有的导；游信息，包括导游姓名，手机号，身份证；号。；2. 如此处录入导游姓名，下拉框中为“无；数据”，说明该导游不在系统库中，需要；在《导游管理》功能中添加导游信息。；3.联系人，默认为所选导游，如有多个导游，；此处需要进行选择。；1；2；3","img":"assets/ppt-mapped/full/后台-团队冲红-P145.png","caption":"后台培训P91-155｜第 145 页"},{"page":146,"title":"计调-预约下单","body":"1.在红框中，选择所需要预订的门票类型，；勾选后，会将所购的票自动显示在下方；“购票信息中”。；2.购票信息中，显示为当前团队所购买的所；有票型，通过上方产品选择进行添加。实；名制大门票需要导入所有游客信息，通过；导入数自动核算购买票数。；3.去除勾选或点击票型后删除按钮，可以去；除购买票型。；1；3","img":"assets/ppt-mapped/full/后台-团队冲红-P146.png","caption":"后台培训P91-155｜第 146 页"},{"page":147,"title":"计调-预约下单","body":"1.所有实名制为“实名”的票型，都需要进行游客信；息导入，点击该票型后“导入”按钮，弹出导入游客；框；2. 可以通过下载系统提供的“导入游客模板”，按文；件要求填写相关数据进行游客信息的导入，点击；“模板导入”进行导，速度快一些。；3.您ERP系统中直接导出的游客信息 ，直接导入系统，；可以自动识别到游客姓名和身份证号，请 确保您ERP；系统导出的数据中有“游客姓名”和“游客身份证”；列。（速度慢一点儿）；3.将完整需要购票的游客Excel表信息准备好后 ，拖动；至大框，系统自动识别并上传，如有问题，会在框中；进行提示，必须要是 正确的身份证信息，且不能重复，；4.完成导入后务必点击“确定”按钮！；1；2；3；4","img":"assets/ppt-mapped/full/后台-团队冲红-P147.png","caption":"后台培训P91-155｜第 147 页"},{"page":148,"title":"计调-预约下单","body":"门票不同年龄层会有不同票型：；可以通过门票名称或门票的备注说明查看。；景区大门票是实名制，在导入后会自动识别所有游；客的年龄，您可以将所有游客信息填写在一个；EXCEl文档中，分别点击不同门票后的“导入”按；钮，符合年龄的游客会成功导入，不符合年龄的游；客，系统自动识别拦截并提示，点击“确定”按钮；确认本次导入信息。；您可以再选择另一个票型将所有游客再次导入 ，系；统会自动识别符合该门票要求的游客成功导入，不；符合要求的拦截。；最后2个年龄层次的游客数相加应该等于购买门票；的游客总数。；2点击；导入；可下载模板；1.可下载模板；3.填写模板；游客信息；5.提示失败详情；5.提示导入情况；4.拖入EXCEL；确认购；票数；6.点击确；定","img":"assets/ppt-mapped/full/后台-团队冲红-P148.png","caption":"后台培训P91-155｜第 148 页"},{"page":149,"title":"计调-预约下单","body":"1.如实名制票不导入游客信息，也可选择点击“编；辑”按钮，人工单个录入。如导入的游客信息有误，；也可点击“编辑”进行单个修改。当然也可以重新；进行导入，重新导入将会覆盖所有原已导入数据 。；编辑完游客必须点击“确认修改”按钮!；2.如未导入数据，需要单个录入游客信息，点击；“新增游客”按钮，点击一次，下方新增一行游客；信息行，可以进行添加。；3.如需要删除，可以点击单条信息后方“删除”按；钮，也可以勾选所要删除的信息，批量进行删除。；4. 点击“暂存”，可以临时存储已填信息，后续可；以继续编辑；5.点击“提交订单”，则代表已确认购买信息，提；交订单到景区。；1；2；3；4 5","img":"assets/ppt-mapped/full/后台-团队冲红-P149.png","caption":"后台培训P91-155｜第 149 页"},{"page":150,"title":"计调-预约下单成功","body":"提交订单成功后，显示预约成功信息，；1.点击“查看详情”，进入查看已预约好的订单详情页；2.点击“继续预约”，可以继续下单；1 2","img":"assets/ppt-mapped/full/后台-团队冲红-P150.png","caption":"后台培训P91-155｜第 150 页"},{"page":151,"title":"计调-预约下单不满足预约规则","body":"如预约单不满足团队预约规则，会弹出超限；申请弹窗，提示当前规则说明及问题说明；旅行社需要填写特殊报备原因，经景区审批；后导游方可入园。；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P151.png","caption":"后台培训P91-155｜第 151 页"},{"page":152,"title":"计调-查看订单","body":"1.点击“订单管理”-“团队订；单”菜单，可以查看所有已下订；单；2. “查看订单”-查看该订单详；情 ；；3.“修改订单”- 修改已下订单，；修改订单会按下单规则重新测算；人数和下单时间，以最后一次修；改的订单信息为准；如导游已到；窗口确认订单，则不再允许修改。；4.“取消订单”- 只要导游还未；在景区窗口确认入园，都可以随；时取消。；1；2 3 4；订单状态说明：；待确认-已下单成功但导游还未到景区窗口（可取消和修改）；待使用– 导游已到窗口确认入园，但门票还未全部检票；已完成– 游客已全部检票或已退票；完成；已关闭 – 导游已确认入园，但后续全部退票；已过期– 已下单，但团队未到景区，也未取消订单，自动过期。；订单类型说明：“计划订单”为旅行社提前下的订单","img":"assets/ppt-mapped/full/后台-团队冲红-P152.png","caption":"后台培训P91-155｜第 152 页"},{"page":153,"title":"计调-查看订单","body":"1.检票状态栏为该订单所有门；票的检票和退票数；2.检票状态下方列表为该订单；中每种票型的检票和退票情况；3.门票信息，可以通过详细游；客名，手机，证件查询每个游；客门票检票和退票状态。；1；2；3","img":"assets/ppt-mapped/full/后台-团队冲红-P153.png","caption":"后台培训P91-155｜第 153 页"},{"page":154,"title":"计调-退票查询","body":"1. 点击“订单管理”-“退票查询”菜单，可以查询所有已退的票；2.“已完成”标签中的订单为有部分检票有部分退票的订单 ，“已关闭”标签中的订单为全部退票的订单。；3. 点击“查看订单”进入订单详情页。订单退票分两种，未检票和已检票但由于误检或游客原因，强制退的票。 未检的票系统在游玩当日晚上22；点以后自动退票。；1；2；3","img":"assets/ppt-mapped/full/后台-团队冲红-P154.png","caption":"后台培训P91-155｜第 154 页"},{"page":155,"title":"特别注意事项1","body":"02；1、景区大门票只能旅行社通过系统下单，包含了景区大门票的票类，实名制，必须要有每位游客的 身份证信息，否则无法成功下单。；2、景区内项目：导游可以在景区窗口线下签单或购票。；3、门票验票：客人刷身份证/纸质票入园；4. 每个团仅允许下一个计划订单，如团队游客身份信息或团队人数、团期，导游有调整，请及时修改订单，在导游到景区窗口做订单确认；前随时可做修改并重新提交。；5.游客增加或变更请务必修改，如减少，游客不入园，预约单没有验票的，系统每晚 10点会自动退票（ 必须是未验票，已验票的不退票）；6.全陪导游如无导游证，请多下一张门票（门票数>团队人数），当该全陪导游当游客做处理，团队人数可少于门票数。如 全陪导游有导游；证，可不用为其下单。；7. 导游必须要提交导游身份证，导游手机号和导游证等信息。；8. 团队可以在团期范围内到景区游玩 ，预定日期为预计到景区时间，如不一致不影响导游在团期内入园，但 团期如有变更必须要修改订单。；9. 司陪票走线下出票","img":"assets/ppt-mapped/full/后台-团队冲红-P155.png","caption":"后台培训P91-155｜第 155 页"}]},{"title":"团队财务与窗口确认","source":"后台培训P156-177","steps":[{"page":156,"title":"团队线上预约平台","body":"财务操作指引","img":"assets/ppt-mapped/full/后台-团队冲红-P156.png","caption":"后台培训P156-177｜第 156 页"},{"page":157,"title":"财务-登录系统","body":"请收藏系统登录地址：https://teambooking.ly.com/；首次登录；可以选择“短信登录”方式；通过手机号+验证码；登录”呀诺达-团队线上预约平；台”；如登录不了，；请确认旅行社管理员是否正确；添加了您的手机号。；首次登录请选择“短信登录”","img":"assets/ppt-mapped/full/后台-团队冲红-P157.png","caption":"后台培训P156-177｜第 157 页"},{"page":158,"title":"财务-登录系统","body":"1登录后，请点击界面右上方头像下的；“账号及密码”；2.修改用户昵称，账号或密码；3. 后续则可通过账号和密码进行系统登录；点击头像下方的“账号及密码”；3；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P158.png","caption":"后台培训P156-177｜第 158 页"},{"page":159,"title":"财务-对帐报表","body":"1. 点击“财务管理”-“对帐报；表”菜单，进入报表查询界面；2. 可以通过游玩日期和导游姓名；组合查询团队账务信息；3. 点击“导出数据”可以导出当；前查询出来的报表结果数据；3；21","img":"assets/ppt-mapped/full/后台-团队冲红-P159.png","caption":"后台培训P156-177｜第 159 页"},{"page":160,"title":"团队管理-团队预约订单","body":"（售票员）","img":"assets/ppt-mapped/full/后台-团队冲红-P160.png","caption":"后台培训P156-177｜第 160 页"},{"page":161,"title":"售票员操作流程 – 搜索计划订单","body":"1. 确认该团队是否启用了线上团票系统，意味着是否需要人工录票；2. 收导游行程单，团队管理->团队预约订单 ->点“待确认”标签页，搜索条件选择导游手机或导游姓名 ，搜索，确认搜索到的旅行社和导游，；对下团号（行程单号）和人数 ，点击“订单确认”按钮。（如果“待确认”里找不到 ，选择全部后搜索，可能是AB团多导游，已确认过订；单）；1；2；3；4；订单确认","img":"assets/ppt-mapped/full/后台-团队冲红-P161.png","caption":"后台培训P156-177｜第 161 页"},{"page":162,"title":"售票员操作流程 – 查看/修改/确认计划订单","body":"1. 进入团队预约订单详情页，可在门票信息下直接 查看当前计划订单中旅行社下的 票型和票数；✓ 实际入园人数>此处大门票条数，告知导游让旅行社修改订单，修改成功后，需要刷新页面。；✓ 实际入园人数<此处大门票条数，不入园的和免票儿童不刷证入园即可，请务必提醒导游 符合要求的免票儿童不要刷证 ，否则核算票数。；1","img":"assets/ppt-mapped/full/后台-团队冲红-P162.png","caption":"后台培训P156-177｜第 162 页"},{"page":163,"title":"售票员操作流程 –查看/修改/确认计划订单","body":"2. 如旅行社有漏游客或下错游客的情况，在一键确认前发现， 先报备，确认情况后，现可增加旅行社当前票型的游客信息和票数；（1）点击对应需要增加票型前的增购按钮，弹出增购页进行增购。分为两种票型， 1种为实名制票，1种为非实名制票；（2）实名制大门票类，弹窗中填写增购数量后需要填写对应人数的游客信息 （3）非实名制项目票类，弹窗后只需要填写增购数量；（4）如录入的游客与原计划订单游客信息有 重复，系统会提示并直接删除。；1；3；2；4","img":"assets/ppt-mapped/full/后台-团队冲红-P163.png","caption":"后台培训P156-177｜第 163 页"},{"page":164,"title":"售票员操作流程 –查看/修改/确认计划订单","body":"3. 如已新增了增购门票，完成后会在计划订单页 刷新最新购买门票张数 ，请确认清楚后再“一键确认”；4. 如已新增了增购门票，完成后会自动在下方游客信息最后新增门票 ，如添加错误，可以删除后重新添加，最后下单只按票型后最新张数下单 ，游；客也只按游客信息中未删除的游客下单。；1；2；3","img":"assets/ppt-mapped/full/后台-团队冲红-P164.png","caption":"后台培训P156-177｜第 164 页"},{"page":165,"title":"售票员操作流程 - 查看/修改/确认计划订单","body":"5. 如门票数>团队人数，有全陪导游且已购买门票，确认 全陪是否有导游证，有导游证，先在票务系统出“司陪票”后 ，再点击“一健确认”；弹出提示：购买的票中与票务系统中有重复票，说明刚刚在 票务系统下的导游司陪票重复 了，点击“删除”，系统自动会删除重复票；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P165.png","caption":"后台培训P156-177｜第 165 页"},{"page":168,"title":"售票员操作流程 – 启用预约规则后查看审批","body":"1. 进入团队预约订单列表页，如该团队人数或预约时间超过规定，在下单时系统自动触发超限审批；在“订单确认”按钮后就会出来“审批查看”按钮，只要旅行超过规定，此按钮就会出现 ，审批通过，后续可一键下单，不通过详情页无法下单。；2. 如发现“查看审批”按钮，通知预订部要求领导审批！；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P168.png","caption":"后台培训P156-177｜第 168 页"},{"page":170,"title":"售票员操作流程 – 下单后增购","body":"1；1. 如在“一键确认”后，需要替导游下增购单，或补录游客大门票的，可搜索到该导游当天的计划订单 ，点击操作按钮处会显示“增购”按钮；特别注意：；（1）只有计划订单后才会有增购按钮，导游自已增购的订单后无增购按钮。；（2）只有当天的计划订单可增购，过了有效期无法增购","img":"assets/ppt-mapped/full/后台-团队冲红-P170.png","caption":"后台培训P156-177｜第 170 页"},{"page":171,"title":"售票员操作流程 – 下单后增购","body":"1.点开增购后，请先核对当前“旅行社、导游和游玩日期 ”信息，如一团多导，请选择当前负责的导游，避免增购的团队错误。；2.所有该旅行社允许售卖的有效票型列在右侧票型列表里，点击该票型就可添加至左侧售卖信息框中。如右侧票型被 蓝色框选定，则说明已是当前；售卖票型，如需要删除请于左方删除。；3. 默认售卖1张票，可根据实际情况调整数量 ，如为；实名票，添加数量后下方会要求填写游客信息，非实；名票仅需填写增购数量。；4. 点击票型名称后的绿色删除按钮，直接删除当前售；卖票型。；5. 点击游客信息后删除按钮，删除当前已添加的游客；信息同时扣减门票张数，如游客信息全部填写后， 减；少增购数量，侧从最下面游客开始自动删除 对应减少；量的游客。；6. 如增购的实名票中有所原计划订单重复的游客 ，系；统会提示并自动删除门票。；1；2；3；4；5","img":"assets/ppt-mapped/full/后台-团队冲红-P171.png","caption":"后台培训P156-177｜第 171 页"},{"page":172,"title":"一团多导特别注意点","body":"1.AB团多导游，搜索导游列表页查不到，查看导游姓名前是否有 “多”字标签，如有，点击进入 订单详情后可以看到多个导游；2.AB团的订单，第一个导游来景区后就全部确认整团入园人数 ，实际>整团门票数，需要让旅行社调整，实际<整团门票数，可以不管；3.AB团第一个导游确认后，第二个导游实际可以直接带团入园 ，如到窗口，订单不在“待确认”里， 在“待使用”里。；4.AB团多导游，每个导游可以自助下单二销票 ，不能刷身份证检票 ，但可以通过一票多人扫码检票 。","img":"assets/ppt-mapped/full/后台-团队冲红-P172.png","caption":"后台培训P156-177｜第 172 页"},{"page":173,"title":"团队管理-导游管理","body":"（售票员）","img":"assets/ppt-mapped/full/后台-团队冲红-P173.png","caption":"后台培训P156-177｜第 173 页"},{"page":174,"title":"售票员操作流程 – 修改导游登录手机号","body":"1.如导游报手机号未搜索到导游手机号 的，请搜索导游姓名，记得搜索到后确认导游身份证号、当前团队旅行社 ，防止同名同姓；2.在订单列表中的导游手机号，为旅行社下单时的导游手机号，点击 “订单确认”进详情页后 ，会显示导游订单上手机和登录的手机号 。；3.如订单手机号与登录手机号不相符，复制需要修改的导游证件号 ，进入“导游管理”菜单进行调整；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P174.png","caption":"后台培训P156-177｜第 174 页"},{"page":175,"title":"售票员操作流程 – 修改导游登录手机号","body":"1. 点击进入“团队管理-> 导游管理”页面；2. 输入已复制好的需要修改的导游身份证号，点“查询”（建议以身份证号为主搜索，避免改错人）；3. 点击该导游后“修改”按钮，弹出修改信息框；4. 核对导游信息后，修改该导游手机号，点击“确认”， 完成后会提示“该导游的系统登录手机号已调整成功，请使用该手机号重新登录。”；1；4；3；2","img":"assets/ppt-mapped/full/后台-团队冲红-P175.png","caption":"后台培训P156-177｜第 175 页"},{"page":176,"title":"售票员操作流程 – 修改导游登录手机号","body":"1.修改后，再进入“团队预约订单”页面， 用最新更换的手机号搜索 ，当前导游所有历史订单全部可以搜索到；2.列表页显示的导游手机号依然是旅行社下单时的手机号 ，点击进入详情页后，会显示下单时的手机号和当前登录手机号 。；1；2","img":"assets/ppt-mapped/full/后台-团队冲红-P176.png","caption":"后台培训P156-177｜第 176 页"},{"page":177,"title":"售票员操作流程 – 修改导游登录手机号","body":"特别提示：；1.导游可以用已修改的最新手机号登录，但检票详情；页中导游的电话号显示为旅行社下单时的手机号；2.票务系统中和手持设备查询该订单时，导游的手机；号同样也为旅行社下单时手机号","img":"assets/ppt-mapped/full/后台-团队冲红-P177.png","caption":"后台培训P156-177｜第 177 页"}]}]},{"id":"guide","label":"内导业务岗位","title":"内导产品、人员、开单、结账与查询","desc":"后台维护内导资料，窗口完成内导开单、结账和订单追溯。","tasks":[{"title":"后台内导管理","source":"后台培训P182-188","steps":[{"page":183,"title":"内导管理- 内导产品管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-内导-P183.png","caption":"后台培训P182-188｜第 183 页"},{"page":184,"title":"内导管理- 新增内导产品","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-内导-P184.png","caption":"后台培训P182-188｜第 184 页"},{"page":185,"title":"内导管理- 导游分组管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-内导-P185.png","caption":"后台培训P182-188｜第 185 页"},{"page":186,"title":"内导管理- 内导管理","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-内导-P186.png","caption":"后台培训P182-188｜第 186 页"},{"page":187,"title":"内导管理- 内导新增与编辑","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-内导-P187.png","caption":"后台培训P182-188｜第 187 页"},{"page":188,"title":"内导管理- 内导订单查询","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/后台-内导-P188.png","caption":"后台培训P182-188｜第 188 页"}]},{"title":"窗口内导开单与结账","source":"窗口V4 P40-63","steps":[{"page":41,"title":"售票窗口-内导开单-散客","body":"可选择计时收费或固定收费产品，确认游玩日期，再选择是散客还是团队；点击此处选择内导","img":"assets/ppt-mapped/full/窗口-操作手册-P041.png","caption":"窗口V4 P40-63｜第 41 页"},{"page":42,"title":"售票窗口-选择内导","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P042.png","caption":"窗口V4 P40-63｜第 42 页"},{"page":43,"title":"售票窗口-散客内导计时收费-开单收取固定押金","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P043.png","caption":"窗口V4 P40-63｜第 43 页"},{"page":44,"title":"售票窗口-散客内导固定收费 -开单收取固定费用","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P044.png","caption":"窗口V4 P40-63｜第 44 页"},{"page":45,"title":"售票窗口-散客内导计时收费-支付订单确认","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P045.png","caption":"窗口V4 P40-63｜第 45 页"},{"page":46,"title":"售票窗口-散客内导固定收费-支付订单确认","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P046.png","caption":"窗口V4 P40-63｜第 46 页"},{"page":48,"title":"售票窗口-内导开单-团队","body":"可选择计时收费或固定收费产品，确认游玩日期，再选择是散客还是团队","img":"assets/ppt-mapped/full/窗口-操作手册-P048.png","caption":"窗口V4 P40-63｜第 48 页"},{"page":49,"title":"售票窗口-选择内导","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P049.png","caption":"窗口V4 P40-63｜第 49 页"},{"page":50,"title":"售票窗口-选择团队订单","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P050.png","caption":"窗口V4 P40-63｜第 50 页"},{"page":51,"title":"售票窗口-团队内导固定收费","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P051.png","caption":"窗口V4 P40-63｜第 51 页"},{"page":52,"title":"售票窗口-团队内导计时收费-支付订单确认","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P052.png","caption":"窗口V4 P40-63｜第 52 页"},{"page":53,"title":"售票窗口-团队内导固定收费-支付订单确认","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P053.png","caption":"窗口V4 P40-63｜第 53 页"},{"page":55,"title":"售票窗口-内导结帐","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P055.png","caption":"窗口V4 P40-63｜第 55 页"},{"page":56,"title":"售票窗口-内导-结帐核算","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P056.png","caption":"窗口V4 P40-63｜第 56 页"},{"page":57,"title":"售票窗口-内导-结算核算-退款","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P057.png","caption":"窗口V4 P40-63｜第 57 页"},{"page":58,"title":"售票窗口-内导-结算核算-补收","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P058.png","caption":"窗口V4 P40-63｜第 58 页"},{"page":59,"title":"售票窗口-内导开单后退单","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P059.png","caption":"窗口V4 P40-63｜第 59 页"},{"page":60,"title":"售票窗口功能操作说明","body":"内导订单查看；交易记录查看","img":"assets/ppt-mapped/full/窗口-操作手册-P060.png","caption":"窗口V4 P40-63｜第 60 页"},{"page":61,"title":"售票窗口-散客内导订单查看","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P061.png","caption":"窗口V4 P40-63｜第 61 页"},{"page":62,"title":"售票窗口-散客内导交易记录查看","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P062.png","caption":"窗口V4 P40-63｜第 62 页"},{"page":63,"title":"售票窗口-散客内导交易记录详情","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/窗口-操作手册-P063.png","caption":"窗口V4 P40-63｜第 63 页"}]}]},{"id":"channel","label":"市场 / 渠道岗位","title":"分销商、授权产品、资金与短信","desc":"管理分销商、产品授权、充值流水与短信模板记录。","tasks":[{"title":"分销商管理","source":"后台培训P189-198","steps":[{"page":190,"title":"分销管理- 分销商管理","body":"所有OTA、旅散、自营等外部分销商配置，全部在“ 分销商管理”中；此功能可以配置分销商对接接口，可以配置该分销商允许分销的产品，也可以实时查询该分销商账户余额，充值记录和资金流水；分销商启用，即允许分销商从其他平台下单，禁用，则分销商下单会失败","img":"assets/ppt-mapped/full/后台-渠道短信-P190.png","caption":"后台培训P189-198｜第 190 页"},{"page":192,"title":"分销管理- 分销商管理","body":"目前，对接方式为“直连”统一处理为票务系统提供接口给分销商 ，旅散和自营平台全部使用此方式，无需配置对接参数；对接方式为“平台统一对接”，即连小泥人平台，对接平台 选择小泥人，下方配置小泥人平台对接的相关 分销商ID（研发配置处理）","img":"assets/ppt-mapped/full/后台-渠道短信-P192.png","caption":"后台培训P189-198｜第 192 页"},{"page":193,"title":"分销管理- 分销商管理","body":"每个分销商的渠道配置，作用于市场部未来根据不同渠道进行入园统计的需求，此处请选择该渠道在整体架构中准确的渠道。","img":"assets/ppt-mapped/full/后台-渠道短信-P193.png","caption":"后台培训P189-198｜第 193 页"},{"page":194,"title":"分销管理- 分销商管理","body":"每个渠道后的“产品管理”主要用；来控制该分销商可以分销的门票产；品；特别注意：；对接方式为“统一对接平台”的，；所有该平台对接的商品都需要统一；配置到该平台（如小泥人平台），；该平台下的所有渠道（如小泥人对；接的抖音，携程，美团，同程等）；无需配置对应产品，所有对应关系；需要在小泥人平台中自行配置。；对接方式为“直连”的，需要配置；该分销商的可销售产品。；“全部”标签中产品，为所有票库配置为“团散类型=散客且销售渠道=线上预订”的；产品（包含了已上架和已下架的）；“已授权”标签中产品,为所有该分销商可下单产品；“已解绑”标签中产品为所有该分销商不可下单产品；门票后“绑定”按钮功能为，将该门票产品授权给该分销商；门票后“解绑”按钮功能为，将该门票产品从该分销商可分销产品中去除；支持勾选对应门票产品，批量进行授权和解绑；点击“查看”该门票详情","img":"assets/ppt-mapped/full/后台-渠道短信-P194.png","caption":"后台培训P189-198｜第 194 页"},{"page":196,"title":"分销管理- 充值申请","body":"如分销商是限额的，可以通过“充值申请”中“充值”按钮来给各分销商进行充值；如点击“分销商管理”页中某个分销商后的“充值记录” 按钮，页面会自动跳转到该页，并查询所选分销商的所有充值记录","img":"assets/ppt-mapped/full/后台-渠道短信-P196.png","caption":"后台培训P189-198｜第 196 页"},{"page":197,"title":"分销管理- 资金流水","body":"如点击“分销商管理”页中某个分销商后的“资金流水” 按钮，页面会自动 跳转到该页，并查询所选分销商的所有充值、下单消费及退款记录","img":"assets/ppt-mapped/full/后台-渠道短信-P197.png","caption":"后台培训P189-198｜第 197 页"}]},{"title":"短信管理","source":"后台培训P199-202","steps":[{"page":200,"title":"短信管理- 短信模板管理 – 新增/编辑模板","body":"在“短信模板管理”中可以添加所需要发送的短信模板，编辑短信内容，参数设置按“模板参数设定”中进行配置，注意，必须要有 【】号；最长短信70个字符，超长会分开发送，每个产品发送一条短信，如有订单中有两个产品，会发送两条短信！","img":"assets/ppt-mapped/full/后台-渠道短信-P200.png","caption":"后台培训P199-202｜第 200 页"},{"page":201,"title":"短信管理- 短信模板管理 – 关联门票","body":"每个模板后有“关联门票”按钮，点击弹出“选择产品”弹窗，里面会显示所有“团散类型 =散客且销售渠道=线上预订”的门票；“全部”标签中产品，为所有票库配置为“团散类型=散客且销售渠道=线上预订”的产品（包含了已上架和已下架的）；“已配置”标签中产品,为所有发送该模板短信的产品，每个产品仅允许配置一种模板，如配置在了该模板弹窗中，其他模板弹窗不可见该产品，如该模；板还未配置产品，未配置项为空。；“未配置”标签中产品为所有该还未配置短信模板的产品，所有未配置弹窗产品都一致，说明该产品还未配置过短信模板，如所有产品都已配置，未配；置项目则为空。；门票后“配置”按钮功能为，将该门票产品的发送短信配置为当前模板；门票后“解绑”按钮功能为，将该门票产品的发送短信去除当前模板；支持勾选对应门票产品，批量进行配置和解绑","img":"assets/ppt-mapped/full/后台-渠道短信-P201.png","caption":"后台培训P199-202｜第 201 页"},{"page":202,"title":"短信管理- 短信记录","body":"每条短信发送都会存储发送记录，可在短信记录中查看","img":"assets/ppt-mapped/full/后台-渠道短信-P202.png","caption":"后台培训P199-202｜第 202 页"}]}]},{"id":"checkin","label":"检票岗位","title":"检票 APP、现场核验与套票子票","desc":"按门票状态、核验方式和套票子票完成检票与异常处理。","tasks":[{"title":"检票岗位SOP","source":"检票SOP P1-33","steps":[{"page":1,"title":"呀诺达-程程票票务系统","body":"检票SOP；2025/11/07","img":"assets/ppt-mapped/full/检票-SOP-P001.png","caption":"检票SOP P1-33｜第 1 页"},{"page":4,"title":"检票PDA功能操作说明","body":"系统登录及功能说明","img":"assets/ppt-mapped/full/检票-SOP-P004.png","caption":"检票SOP P1-33｜第 4 页"},{"page":6,"title":"PDA- 登录","body":"在PDA桌面找到；“门票核销系统”图标点击进入；1.使用最新配发的生产账号和密码登录应用；生产环境最新账号前缀有“ynd”三个字符；2.如该页面弹出更新弹窗，请点击更新，会；跳转到浏览器页面，请下载最新应用并确认；安装成功；4.如IT需要了解设备的ID，请退出到此登录；页面，点击下方齿轮按钮，查看设备ID，报；给IT。","img":"assets/ppt-mapped/full/检票-SOP-P006.png","caption":"检票SOP P1-33｜第 6 页"},{"page":7,"title":"PDA- 首页","body":"景区名称显示，请务必确保登录后；景区名为“呀诺达景区门票核销系统”；否则不是生产环境系统，请使用正确的生产账号重登录；站点今日可核销：当前设备所属站点今日待检票张数；站点今日已核销：当前设备所属站点今日已检票张数；本设备已核销：当前设备今日已检票张数；一人一票：进入单门票检票或单独身份证检票页 一票多人：进入一票多人按票型批量检票或团；队导游票型查询页；通道：显示当前设备所属通道名称；设备：显示当前设备名称；特别注意：如登录后发现未显示通道与设备，；说明不可检票，请联系IT配合检查，如有必要；可退到登录界面，提供给IT设备ID辅助检查。；IT调整后，请下拉刷新页面，直到显示通道名；和设备名方可检票！；统计查询：针对本站点所有通道独立进行；待接待，已接待数统计查询；系统配置：查看当前登录账号，当前登录站点，；通道，设备名，手动触发版本更新以及退出账；号等功能页。","img":"assets/ppt-mapped/full/检票-SOP-P007.png","caption":"检票SOP P1-33｜第 7 页"},{"page":8,"title":"检票PDA功能操作说明","body":"一人一票查询/检票","img":"assets/ppt-mapped/full/检票-SOP-P008.png","caption":"检票SOP P1-33｜第 8 页"},{"page":9,"title":"PDA- 散客一人一票 – 信息查询","body":"检票页面中，最上面有“一人一票”和“一票多人”标签；页可以切换，首页从哪个菜单进入就会定位到哪个标签，；检票页无需切换到首页调整检票功能，只需要在标签页中；来回切换即可。；是否开启自动检票：如开启，设备扫码或扫证后，即刻执；行查询门票和检票操作，无需要人工点检票，关闭，仅查；询，但不会执行检票操作。；票号/身份证/证件号：可以使用PDA硬件设备按钮直接扫；码查询，也可以在手机上点击右侧图标按钮进行拍照或扫；码，再点击查询。手机身份证扫码必须点击拍照按钮！；展开订单详情：展开查看该订单详情信息；收起订单详情：收起该订单详情信息；****","img":"assets/ppt-mapped/full/检票-SOP-P009.png","caption":"检票SOP P1-33｜第 9 页"},{"page":10,"title":"PDA- 散客一人一票 – 待检票/已检票","body":"票号/证件号检票：票号扫码票，以；及正常散客身份证扫码，线下团队游；客身份证扫码的票，全部出现在此标；签中。括号后为该游客可检门票数。；检票：所有可以被检的门票，都会标；识为“待检票”，红色标注；（1）按票号查询时，查询后默认被；勾选，勾选后点击下方“检票”按钮；就即刻执行检票；（2）按证件号查询时，如有多个票；可以被检票，默认不会勾选，请自行；勾选所需要检的票后批量检票；检票成功：检票成功后，页面；会弹出检票成功提示，而后自；动刷新页面，此时该门票即会；标注为“已检票”，门票状态；也会变更为部分检票或全部检；票。；所有当天在有效期内的已检票；的票再次查询，状态都为已检；票，除非退票变无效票。；已检票；********","img":"assets/ppt-mapped/full/检票-SOP-P010.png","caption":"检票SOP P1-33｜第 10 页"},{"page":11,"title":"PDA- 散客一人一票 – 无效票","body":"无效票：所有不能检票的票都会标注无效票，且无检票按钮；无效票原因：；1.门票状态为非可检票，比如；（1）已退票的票；（2）待付款的票；（3）待确认的票，门区特别注意：如有线上票需要窗口确认游客身份的，如；“粉丝票/海南人证”票等，游客在窗口未确认前无法入园，识别无效票，如看；到待确认门票为无效票请让游客去窗口核实身份并确认入园！；2.不在门票有效期内的票；3.提前X小时下单未到检票时间的票，检查下单时间；4.当前设备所属通道不能检票；5.M选N的票，已达到了检票上限（可检查已检和待检子票）；5.无效的票号；6.无效的证件号；特别注意：目前子票的；检票通道虽然是实时查；询，但子票检票通道变；更，生效时间几分钟，；如有特殊情况当天变更；1分钟内，可能会出现；通道不能检票情况！；一般不会有此情况！测；试期间可能会有变更。；****","img":"assets/ppt-mapped/full/检票-SOP-P011.png","caption":"检票SOP P1-33｜第 11 页"},{"page":12,"title":"PDA- 团队一人一票","body":"团队一人一票与散客一人一票查询/检票方式完全一致；不同的是：；1.团散类型会显示“团队”便于区分游客类型；2.会显示对应旅行社名和外导名+联系方式；3.购票人；（1）线上散客，购票人为实际购票人；（2）线下散客，为订单中随机一名游客；（3）团队，购票人为外导，可通过购票人和购票人联系方式找到外；导；****；票号/证件号检票：票号扫码票，以及正常散客身份证扫码，线下团；队游客身份证扫码的票，全部出现在此标签中。括号后为该游客可检；门票数。；团队增购可绑门票：线上团队导游增购时，只下票数，默认无游客信；息，但系统会自动绑定该团队所有游客，即如该团队中有游客身份证；被扫码后，在此标签页中即会出现所有该团导游增购，但标识的门票；可根据实际情况进行选择检票。括号后为该游客可检票门票数","img":"assets/ppt-mapped/full/检票-SOP-P012.png","caption":"检票SOP P1-33｜第 12 页"},{"page":13,"title":"检票PDA功能操作说明","body":"一票多人查询/检票","img":"assets/ppt-mapped/full/检票-SOP-P013.png","caption":"检票SOP P1-33｜第 13 页"},{"page":14,"title":"PDA- 散客/团队一票多人 – 信息查询","body":"检票页面中，最上面有“一人一票”和“一票多人”标签；页可以切换，首页从哪个菜单进入就会定位到哪个标签，；检票页无需切换到首页调整检票功能，只需要在标签页中；来回切换即可。；票型二维码/外导身份证：可以使用PDA硬件设备按钮直；接扫码查询，也可以在手机上点击右侧图标按钮进行拍照；或扫码，再点击查询。手机身份证扫码必须点击拍照按钮！；展开门票详情：展开查看该门票详情信息；展开订单详情：展开该订单详情信息；散客：只需要扫票型二维码；团队：可以通过外导身份证/手机号查询团队票；外导手机号：人工输入外导手机号查询；内导手机号：需要窗口关联了内导才能查到，如窗口未关；联查不到。","img":"assets/ppt-mapped/full/检票-SOP-P014.png","caption":"检票SOP P1-33｜第 14 页"},{"page":15,"title":"PDA- 散客/团队一票多人 – 信息查询/检票","body":"点击外导后图标，可以迅速填；写外导手机到输入框，再点击；查询，可以查到该外导1个月；内所有门票；检票数：点击开关按钮，；检票数后加减：按人数检票。；点击“检票”，弹出确认窗口，；确认当前检票数量是否准确，；“确认检票”就会按本次检票数","img":"assets/ppt-mapped/full/检票-SOP-P015.png","caption":"检票SOP P1-33｜第 15 页"},{"page":16,"title":"PDA- 散客/团队一票多人 – 按游客单独检票（门区关注）","body":"点击票名；选择检票人；点击检票；完成检票跳回列表页；再次点击进入，可查看已检票","img":"assets/ppt-mapped/full/检票-SOP-P016.png","caption":"检票SOP P1-33｜第 16 页"},{"page":17,"title":"PDA- 散客/团队一票多人 – 已检票","body":"检票成功：检票成功后，页面；会弹出检票成功提示，而后自；动刷新页面，此时该门票即会；标注为“已检票”，门票状态；也会变更为部分检票或全部检；票。；所有当天在有效期内的已检票；的票再次查询，状态都为已检；票，除非退票变无效票。；点击“展开门票详情”，可以；查看已检票情况和待检子票；如为“无效票”；显示为无效票；无效票原因，；见《PDA- 散；客一人一票 –；无效票》页面","img":"assets/ppt-mapped/full/检票-SOP-P017.png","caption":"检票SOP P1-33｜第 17 页"},{"page":18,"title":"报表查询","body":"PC票务系统-报表中心；（PC报表必须核对）","img":"assets/ppt-mapped/full/检票-SOP-P018.png","caption":"检票SOP P1-33｜第 18 页"},{"page":19,"title":"PC- 票务系统后台-登录","body":"票务后台地址： https://lvyou-ticket.ly.com/#/login/index；账号密码登录；按最新分配的生产账号登录","img":"assets/ppt-mapped/full/检票-SOP-P019.png","caption":"检票SOP P1-33｜第 19 页"},{"page":20,"title":"PC- 票务系统后台-报表中心","body":"选择自己的站点查询可以按团队和散客票分别查询默认加载当天日期；报表5分钟更新一次，如检票后数据未更新，等待5分钟后检查；是否排斥未检期票：；如果1年的期票，该游客每天；都会在未接待统计中，不方便；核实，如勾选“是否排除未检；期票”，所有期票用户应接待；数会全部不统计。","img":"assets/ppt-mapped/full/检票-SOP-P020.png","caption":"检票SOP P1-33｜第 20 页"},{"page":21,"title":"PC- 票务系统后台-报表中心","body":"只统计已检票数，如第二天退款，已检票数不会累计到第二天扣减，会调整前一天的检票数据。","img":"assets/ppt-mapped/full/检票-SOP-P021.png","caption":"检票SOP P1-33｜第 21 页"},{"page":22,"title":"PC- 票务系统后台-报表中心","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/检票-SOP-P022.png","caption":"检票SOP P1-33｜第 22 页"},{"page":23,"title":"报表查询","body":"PDA-统计查询","img":"assets/ppt-mapped/full/检票-SOP-P023.png","caption":"检票SOP P1-33｜第 23 页"},{"page":24,"title":"PDA- 统计查询","body":"目前以通道维度统计数据，如；项目票一个站点一个通道，基；本PC报表一致，如门区，后；续增加全部通道数据。；建议现可先核对PC报表；暂时不支持未接待数弹出明细，；如需要查询，进PC报表查询，；后续迭代新增功能支持；是否排斥未检期票：；如果1年的期票，该游客每天；都会在未接待统计中，不方便；核实，如勾选“是否排除未检；期票”，所有期票用户应接待；数会全部不统计。；报表5分钟更新一次，如检票后数据未更新，等待5分钟后检查","img":"assets/ppt-mapped/full/检票-SOP-P024.png","caption":"检票SOP P1-33｜第 24 页"},{"page":25,"title":"PDA-系统配置","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/检票-SOP-P025.png","caption":"检票SOP P1-33｜第 25 页"},{"page":26,"title":"PDA- 系统配置","body":"系统配置可以查询；详细登录账号和通道，站点信息；点击版本更新，如有新版本会跳转；浏览器下载更新包，安装完成更新；包即可更新系统。","img":"assets/ppt-mapped/full/检票-SOP-P026.png","caption":"检票SOP P1-33｜第 26 页"},{"page":27,"title":"检票特别注意事项","body":"请按图中标注的入口、字段与按钮顺序操作，并在保存或提交后回到列表核对结果。","img":"assets/ppt-mapped/full/检票-SOP-P027.png","caption":"检票SOP P1-33｜第 27 页"},{"page":29,"title":"检票特别注意事项","body":"一人一票如扫身份证出来多张票，最新待检；票会显示在最前面，如果只有一张待检票，；系统自动勾选，只需要点击检票即可，如果；多张系统不会自动勾选，必须要人工勾选想；要检的票，点击检票才能检！；手持设备检票；门票必须勾选后才能检票成功！！！","img":"assets/ppt-mapped/full/检票-SOP-P029.png","caption":"检票SOP P1-33｜第 29 页"},{"page":30,"title":"检票特别注意事项","body":"程程票检票只有2种模式，；单人身份证或票号检票 –；一人一票；多人门票二维；码检票 –一票多人，无订；单整单检票模式！；如果检票模式错，会直接；查不到游客门票数据，千；万注意！检票前先确认是；什么类型的票！；手持设备检票；散客一人一票；有游客姓名；团队一人一票；有游客姓名+导游姓名；散客/团队一票多人；都有门票数量显示，1人也算一票多人","img":"assets/ppt-mapped/full/检票-SOP-P030.png","caption":"检票SOP P1-33｜第 30 页"},{"page":32,"title":"无效票如何查询","body":"门区检票：；1.先确认是否为需要提前1小时购的票，检查下单时间；2.查门票状态；（1）待确认（特殊身份-海南人/学生）窗口确认（2）待付款（3）已退款；3.“展开订单详情”，检查当前设备所属通道是否能检票；4. “展开订单详情”，检查门票有效期；项目检票：；1. “展开订单详情”，检查当前设备所属通道是否能检票；2. M选N的票，已达到了检票上限（可检查已检和待检子票）；特别注意：目前子票的；检票通道虽然是实时查；询，但子票检票通道变；更，生效时间几分钟，；如有特殊情况当天变更；1分钟内，可能会出现；通道不能检票情况！；一般不会有此情况！测；试期间可能会有变更。；****；检票特别注意事项 – 无效票判断","img":"assets/ppt-mapped/full/检票-SOP-P032.png","caption":"检票SOP P1-33｜第 32 页"}]},{"title":"套票检票","source":"检票套票 P1-13","steps":[{"page":1,"title":"呀诺达-程票票票务系统","body":"换票流程优化专项说明与操作手册；2026/3/31","img":"assets/ppt-mapped/full/检票-套票-P001.png","caption":"检票套票 P1-13｜第 1 页"},{"page":2,"title":"窗口换票流程优化专项","body":"背景和目标","img":"assets/ppt-mapped/full/检票-套票-P002.png","caption":"检票套票 P1-13｜第 2 页"},{"page":6,"title":"套票检票票号说明","body":"套票票号结构说明：；XXXX-CT – 代表了套票的主票号，所有OTA由于只设置1张票，所以在OTA上的游客券码都为此票号；例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号；子票号后面会有@+编号 例：主票号@编号","img":"assets/ppt-mapped/full/检票-套票-P006.png","caption":"检票套票 P1-13｜第 6 页"},{"page":7,"title":"套票检票 – 闸机","body":"套票身份证检票与原来流程一致；有证的可以查询到可直接刷证入园，一证开一次闸，闸机播报“请进”；无证的无法查询到，无效票，不开闸；套票纸质票与原流程一致；刷票入园，一票开一次闸，闸机播报“请进”；如刷的是手机上的电子二维码且如闸机播报：“2大1小”或“1大1小”；2大1小开3次闸，1大1小开2次闸，双人票开2次闸；刷电子二维码，按套票中已录身份证的人数开闸，一次性可多人入园","img":"assets/ppt-mapped/full/检票-套票-P007.png","caption":"检票套票 P1-13｜第 7 页"},{"page":8,"title":"套票检票 – 手持设备","body":"验票方式：身份证：；套票身份证检票与原来流程一致；请使用“一人一票”检票；有证的可以查询到，无证的无法查询到；验票方式：纸质票；套票纸质票与原流程一致；一张票查询下方出现一张子票","img":"assets/ppt-mapped/full/检票-套票-P008.png","caption":"检票套票 P1-13｜第 8 页"},{"page":9,"title":"套票检票 – 手持设备","body":"套票电子票与原流程不同,请使用“一人一票”检票；但如扫电子二维码会出现该套票下所有子票；选择所需要检的门票；验票方式：手机电子票（线上渠道订单）；如游客已录身份证为“待检票”；可直接检票成功；如游客未录身份证为“待确认”；需要引导去窗口补录证件后再检票","img":"assets/ppt-mapped/full/检票-套票-P009.png","caption":"检票套票 P1-13｜第 9 页"},{"page":10,"title":"套票查询","body":"套票票号结构：；XXXX-CT – 代表了套票的主票号，所有OTA由于只设置1张票，所以在OTA上的游客券码都为此票号 例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号，子票号后面会有&+编号 例：主票号&编号","img":"assets/ppt-mapped/full/检票-套票-P010.png","caption":"检票套票 P1-13｜第 10 页"},{"page":11,"title":"查看套票订单","body":"所有是套票类的门票，在订单详情中都会在门票名称前标注“套票”，点击“套票”可弹框查看套票名称和套票编码。；目前套票的打印序号保持了原来订单的打印序号处理，即按每个票型进行打印序号编码，但排序上，目前会先按套票排序显示，一家人的票需要在一起，然后再按；门票名称打印序号排序","img":"assets/ppt-mapped/full/检票-套票-P011.png","caption":"检票套票 P1-13｜第 11 页"},{"page":12,"title":"报表功能说明","body":"新套票报表与历史报表区别如下：；所有其他报表，线上预订的套票，如套票中有任一子票被检票，在所有报表中，所有子票都会按已检票维度统；计，可能实际该子票还未被检票。；检票数可能会与收银对帐及所有相关财务对帐报表张数不一致，子票不检票，不会影响结算，但会影响入园人；数统计。；原子票销售渠道为售票窗口，套票上线后，所有线上套票打包的子票，销售渠道全部为对应OTA分销商。","img":"assets/ppt-mapped/full/检票-套票-P012.png","caption":"检票套票 P1-13｜第 12 页"}]},{"title":"套票入园核验补充","source":"套票全流程培训","steps":[{"page":6,"title":"官网小程序下单/换票/检票全流程图","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P006.png","caption":"套票全流程培训｜第 6 页"},{"page":7,"title":"其他OTA下单/换票/检票全流程图","body":"请按图中标注顺序完成操作并核对结果。","img":"assets/ppt-mapped/full/套票-全流程-P007.png","caption":"套票全流程培训｜第 7 页"},{"page":11,"title":"套票管理配置 – 总库存模式","body":"填写套票名，建议与套票的主票一致；如窗口售卖套票，可以在此分类中查到；点击后弹窗，配置该套票的子票；套票允许售票窗口与线上一起售卖；配置该套票在哪些售票窗口售卖，特别注意：目前仅支持散客票售卖；如此处配置了语音，在检票时语音提示由原来的“请进”变为此配置语音；特别注意：所有子票依然允许单独售卖，单独配置线上或窗口售卖！","img":"assets/ppt-mapped/full/套票-全流程-P011.png","caption":"套票全流程培训｜第 11 页"},{"page":53,"title":"套票检票票号说明","body":"套票票号结构说明：；XXXX-CT – 代表了套票的主票号，所有OTA由于只设置1张票，所以在OTA上的游客券码都为此票号；例：0OXJTDZ9MJYM8-CT；如使用此主票号查询都可以查到该门票所有子票号；子票号后面会有&+编号 例：主票号&编号","img":"assets/ppt-mapped/full/套票-全流程-P053.png","caption":"套票全流程培训｜第 53 页"},{"page":54,"title":"套票检票 – 闸机","body":"套票身份证检票与原来流程一致；有证的可以查询到可直接刷证入园，一证开一次闸，闸机可播报“套票配置语音提示”；无证的无法查询到，无效票，不开闸；套票纸质票与原流程一致；刷票入园，一票开一次闸，闸机可播报“套票配置语音提示”；套票线上电子二维码；刷电子二维码，按套票中已录身份证的人数开闸，一次性可多人入园，闸机可播报“套票配置语音提示”","img":"assets/ppt-mapped/full/套票-全流程-P054.png","caption":"套票全流程培训｜第 54 页"},{"page":55,"title":"套票检票 – 手持设备","body":"验票方式：身份证：；套票身份证检票与原来流程一致；请使用“一人一票”检票；有证的可以查询到，无证的无法查询到；验票方式：纸质票；套票纸质票与原流程一致；一张票查询下方出现一张子票","img":"assets/ppt-mapped/full/套票-全流程-P055.png","caption":"套票全流程培训｜第 55 页"},{"page":56,"title":"套票检票 – 手持设备","body":"套票电子票与原流程不同,请使用“一人一票”检票；但如扫电子二维码会出现该套票下所有子票；一张检票，所有子票全部检票；验票方式：手机电子票（线上渠道订单）；如游客已录身份证为“待检票”；可直接检票成功；如游客未录身份证为“待确认”；需要引导去窗口补录证件后再检票","img":"assets/ppt-mapped/full/套票-全流程-P056.png","caption":"套票全流程培训｜第 56 页"},{"page":65,"title":"报表功能说明","body":"新套票报表与历史报表区别如下：；1.在“散客订单-线上预订-对帐明细导出”报表中，增加了套票名称和套票编码，如该子票是套票的打包票型，会标注出对应套票的名称和编码，通过套票名称和编；码可以过滤查看对应套票的订单和门票明细情况。；2.所有其他报表，线上预订的套票，如套票中有任一子票被检票，在所有报表中，所有子票都会按已检票维度统计，可能实际该子票还未被检票。检票数可能会与收；银对帐及所有相关财务对帐报表张数不一致，子票不检票，不会影响结算，但会影响入园人数统计。；3.原子票销售渠道为售票窗口，套票上线后，所有线上套票打包的子票，销售渠道全部为对应OTA分销商。","img":"assets/ppt-mapped/full/套票-全流程-P065.png","caption":"套票全流程培训｜第 65 页"}]}]}];
(()=>{
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clean=s=>String(s??'').replace(/https?:\/\/[^；\s]+/gi,'').replace(/\s*；\s*；+/g,'；').trim();
  const rolesSection=document.getElementById('roles');
  if(!rolesSection)return;
  document.querySelectorAll('article.role').forEach(n=>n.remove());
  let host=document.getElementById('manual-role-content');
  if(!host){host=document.createElement('div');host.id='manual-role-content';host.className='wrap';rolesSection.appendChild(host)}
  window.reindexManualSteps=task=>task.querySelectorAll('.step h5 b').forEach((n,i)=>n.textContent=String(i+1));
  const defaultFlowItems=['配置景区','配置景点','配置站点','配置通道','配置设备','配置角色','配置员工','配置系统角色','配置分成项目','配置打印模板'];
  const flowStep=(s,i)=>{const items=Array.isArray(s.items)&&s.items.length?s.items:defaultFlowItems;return '<div class="step flow-step"><div class="step-copy"><h5><b>'+String(i+1)+'</b>'+esc(clean(s.title))+'</h5></div><div class="manual-flow">'+items.map((name,index)=>'<div class="flow-node"><span>'+String(index+1).padStart(2,'0')+'</span><strong>'+esc(name)+'</strong></div>').join('')+'</div></div>'};
  const liveStep=(s,i)=>{
    const layout=String(s.layout||'list').replace(/[^a-z-]/g,'')||'list';
    const notes=s.notes||[];
    const points=(s.points||[]).slice(0,notes.length);
    const markers=notes.map((_,index)=>{
      const point=points[index];
      if(!point)return '';
      const left=Math.max(0,Math.min(100,Number(point[0])||0));
      const top=Math.max(0,Math.min(100,Number(point[1])||0));
      return '<i class="marker" style="left:'+left+'%;top:'+top+'%">'+String(index+1)+'</i>';
    }).join('');
    return '<div class="step annotated-step live-step'+(layout==='phone'?' phone-step':'')+'"><div class="step-copy"><h5><b>'+String(i+1)+'</b>'+esc(clean(s.title))+'</h5></div><div class="annotated-layout"><figure class="annotated-screen layout-'+layout+'"><img src="'+esc(s.img)+'" data-full="'+esc(s.img)+'" alt="'+esc(clean(s.title))+'">'+markers+'</figure><ol class="annotation-list">'+notes.map((note,index)=>'<li><span>'+String(index+1)+'</span><div><strong>'+esc(clean(note[0]))+'</strong><p>'+esc(clean(note[1]))+'</p></div></li>').join('')+'</ol></div></div>';
  };
  for(const role of window.MANUAL_ROLES){
    const meta=window.LIVE_ROLE_META&&window.LIVE_ROLE_META[role.id];
    if(meta){role.title=meta.title||role.title;role.desc=meta.desc||role.desc}
    const article=document.createElement('article');
    article.className='role';
    article.id=role.id;
    let html='<div class="role-top"><span class="pill">'+esc(role.label)+'</span><h3>'+esc(role.title)+'</h3><p>'+esc(role.desc)+'</p></div>';
    const liveTasks=window.LIVE_MANUAL&&window.LIVE_MANUAL[role.id];
    const tasks=liveTasks||role.tasks.filter(task=>task.title!=='票务中心：缆车票配置');
    for(const task of tasks){
      let steps=[...task.steps];
      if(!liveTasks&&task.title==='套票在票务中心的配置')steps=steps.slice(6);
      html+='<div class="task"><h4>'+esc(clean(task.title))+'</h4><div class="steps">';
      steps.forEach((s,i)=>{
        if(s.kind==='flow'||(!liveTasks&&String(s.img).endsWith('后台-票库-P004.png'))){html+=flowStep(s,i);return}
        if(s.live){html+=liveStep(s,i);return}
        const cropped=String(s.img).replace('/full/','/cropped/');
        html+='<div class="step"><div class="step-copy"><h5><b>'+String(i+1)+'</b>'+esc(clean(s.title))+'</h5></div><figure><img src="'+esc(cropped)+'" data-full="'+esc(s.img)+'" alt="'+esc(clean(s.title))+'" onerror="const step=this.closest(\'.step\');const task=this.closest(\'.task\');step.remove();window.reindexManualSteps(task)"></figure></div>';
      });
      html+='</div></div>';
    }
    article.innerHTML=html;
    host.appendChild(article);
  }
})();
